// src/pages/admin/UserManagement.jsx
import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  Typography,
  TextField,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  MenuItem,
  InputAdornment,
  Tooltip,
  Avatar,
} from "@mui/material";
import { Add, Edit, Delete, Search, Security, Create, People } from "@mui/icons-material";
import {
  seedDefaultUsers,
  addUser,
  getAllUsers,
  deleteUser,
  updateUser,
} from "../../db/usersDB";
import EncodingSidebar from "../../components/EncodingSidebar";

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [openAdd, setOpenAdd] = useState(false);
  const [openEdit, setOpenEdit] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [search, setSearch] = useState("");
  const [form, setForm] = useState({
    username: "",
    password: "",
    role: "encoder",
    name: "",
    avatar: null,
  });

  // Load all users
  const loadUsers = async () => {
    await seedDefaultUsers();
    const allUsers = await getAllUsers();
    setUsers(allUsers.map(u => ({ ...u, avatar: u.avatar || null })));
  };

  useEffect(() => {
    loadUsers();

    // Listen for avatar changes from EncodingSidebar
    const handleAvatarChange = (e) => {
      const updatedAvatar = e.detail;
      const username = localStorage.getItem("username");
      setUsers(prev =>
        prev.map(u => (u.username === username ? { ...u, avatar: updatedAvatar } : u))
      );
    };
    window.addEventListener("avatarChanged", handleAvatarChange);
    return () => window.removeEventListener("avatarChanged", handleAvatarChange);
  }, []);

  const handleAddUser = async () => {
  const confirm = window.confirm("Do you want to add this user?");
  if (!confirm) return;

  await addUser(form);
  setOpenAdd(false);
  setForm({ username: "", password: "", role: "encoder", name: "", avatar: null });
  loadUsers();
};

  const handleEditUser = async () => {
  const confirm = window.confirm("Do you want to save changes to this user?");
  if (!confirm) return;

  await updateUser(selectedUser.id, form);
  setOpenEdit(false);
  loadUsers();
};


  const handleDelete = async (id) => {
  const confirm = window.confirm("Are you sure you want to delete this user?");
  if (!confirm) return;

  await deleteUser(id);
  loadUsers();
};

  const handleAvatarUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async () => {
      const avatarData = reader.result;
      setForm(prev => ({ ...prev, avatar: avatarData }));

      // If editing an existing user, persist immediately
      if (selectedUser?.id) {
        await updateUser(selectedUser.id, { avatar: avatarData });
        loadUsers();

        // If the avatar belongs to the logged-in user, update EncodingSidebar
        if (selectedUser.username === localStorage.getItem("username")) {
          window.dispatchEvent(new CustomEvent("avatarChanged", { detail: avatarData }));
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const filteredUsers = users.filter(
    u =>
      u.username.toLowerCase().includes(search.toLowerCase()) ||
      u.name.toLowerCase().includes(search.toLowerCase())
  );

  const renderRoleIcon = (role) => {
    if (role === "admin") return <Security sx={{ fontSize: 18, color: "#007aff", ml: 1 }} />;
    if (role === "encoder") return <Create sx={{ fontSize: 18, color: "#4caf50", ml: 1 }} />;
    return null;
  };

  return (
    <Box sx={{ display: "flex", height: "100vh", background: "#f7f8fa" }}>
      <EncodingSidebar />

      <Box sx={{ flex: 1, p: 4, overflowY: "auto"}}>
            <Typography variant="h4" sx={{ fontWeight: 700, color: "#1c1c1e" }}>
              <People sx={{ fontSize: 35, color: "#007aff", position: "inherit" }} />  User Management
            </Typography>
            
        <Box sx={{ display: "flex", justifyContent: "space-between", mb: 3, flexWrap: "wrap", gap: 2, mt: 2 }}>
          <TextField
            label="Search users..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <Search sx={{ color: "gray" }} />
                </InputAdornment>
              ),
            }}
            sx={{ flex: 1, maxWidth: 300 }}
            size="small"
          />
          <Button
            variant="contained"
            startIcon={<Add />}
            onClick={() => setOpenAdd(true)}
            sx={{ backgroundColor: "#007aff", "&:hover": { backgroundColor: "#005ecb" }, borderRadius: 2, px: 3 }}
          >
            Add User
          </Button>
        </Box>

        <TableContainer component={Paper} sx={{ borderRadius: 2, overflow: "hidden" }}>
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: "#f0f0f5" }}>
                <TableCell sx={{ fontWeight: "700", color: "#333" }}>Username</TableCell>
                <TableCell sx={{ fontWeight: "700", color: "#333" }}>Name</TableCell>
                <TableCell sx={{ fontWeight: "700", color: "#333" }}>Role</TableCell>
                <TableCell sx={{ fontWeight: "700", color: "#333", textAlign: "center" }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredUsers.map(u => (
                <TableRow key={u.id} hover sx={{ "&:hover": { backgroundColor: "#f5f5f7" }, transition: "background 0.2s" }}>
                  <TableCell>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      <Avatar src={u.avatar} sx={{ width: 30, height: 30, bgcolor: "#007aff" }}>
                        {!u.avatar && u.username.charAt(0).toUpperCase()}
                      </Avatar>
                      {u.username}
                    </Box>
                  </TableCell>
                  <TableCell>{u.name}</TableCell>
                  <TableCell sx={{ alignItems: "center", justifyContent: "space-between", textTransform: "capitalize", whiteSpace: "nowrap" }}>
                    <Typography>{u.role}</Typography>
                    {renderRoleIcon(u.role)}
                  </TableCell>
                  <TableCell sx={{ textAlign: "center" }}>
                    <Tooltip title="Edit User">
                      <IconButton color="primary" onClick={() => { setSelectedUser(u); setForm(u); setOpenEdit(true); }}>
                        <Edit />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete User">
                      <IconButton color="error" onClick={() => handleDelete(u.id)}>
                        <Delete />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {["Add", "Edit"].map((type, idx) => {
          const openState = type === "Add" ? openAdd : openEdit;
          const handleClose = () => (type === "Add" ? setOpenAdd(false) : setOpenEdit(false));
          const handleSave = () => (type === "Add" ? handleAddUser() : handleEditUser());

          return (
            <Dialog key={idx} open={openState} onClose={handleClose} fullWidth maxWidth="sm">
              <DialogTitle sx={{ fontWeight: "700", color: "#1c1c1e" }}>{type} User</DialogTitle>
              <DialogContent>
                <Box sx={{ display: "flex", justifyContent: "center", mb: 2 }}>
                  <input
                    accept="image/*"
                    type="file"
                    id={`avatar-upload-${type}`}
                    style={{ display: "none" }}
                    onChange={handleAvatarUpload}
                  />
                  <label htmlFor={`avatar-upload-${type}`}>
                    <Avatar src={form.avatar} sx={{ width: 80, height: 80, cursor: "pointer", mb: 1 }} />
                  </label>
                </Box>

                <TextField label="Username" fullWidth sx={{ mt: 1 }} value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} />
                <TextField label="Password" fullWidth sx={{ mt: 2 }} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} type="password" />
                <TextField label="Full Name" fullWidth sx={{ mt: 2 }} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
                <TextField select label="Role" fullWidth sx={{ mt: 2 }} value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
                  <MenuItem value="admin">Admin</MenuItem>
                  <MenuItem value="encoder">Encoder</MenuItem>
                </TextField>
              </DialogContent>

              <DialogActions>
                <Button onClick={handleClose}>Cancel</Button>
                <Button variant="contained" onClick={handleSave} sx={{ backgroundColor: "#007aff", "&:hover": { backgroundColor: "#005ecb" } }}>
                  {type === "Add" ? "Save" : "Update"}
                </Button>
              </DialogActions>
            </Dialog>
          );
        })}
      </Box>
    </Box>
  );
};

export default UserManagement;