import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import ProfileAdvancedSettings from "./components/ProfileAdvancedSettings";
import ProfileAddressTable from "./components/ProfileAddressTable";
import {
  Box,
  Typography,
  Button,
} from "@mui/material";
import { FileDownload, Print } from "@mui/icons-material";
import { Refresh } from "@mui/icons-material";
import { db } from "../../firebase";
import { collection, getDocs, query, limit, startAfter, orderBy } from "firebase/firestore";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import * as XLSX from "xlsx";

const ProfileAddress = () => {
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [selectedColumns, setSelectedColumns] = useState({
    PROFILE: true,
    ADMIN: true,
    OPPOSITION: true,
    "NO STATUS": true,
  });
  const [allBarangays, setAllBarangays] = useState([]);
  const [selectedBarangays, setSelectedBarangays] = useState([]);
  const [selectedPuroks, setSelectedPuroks] = useState([]);
  const [allPuroks, setAllPuroks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [allTableData, setAllTableData] = useState([]);

  // Fetch all data in single pass for better performance
  useEffect(() => {
    const fetchAllData = async () => {
      // Check if data exists in localStorage
      const cachedData = localStorage.getItem("profileAddressData");
      if (cachedData) {
        try {
          const parsedData = JSON.parse(cachedData);
          setAllBarangays(parsedData.barangays);
          setSelectedBarangays(parsedData.barangays);
          setAllTableData(parsedData.tableData);
          setLoadingProgress(100);
          return; // Skip fetching if cached data exists
        } catch (err) {
          console.warn("Failed to load cached data:", err);
        }
      }

      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const puroksByBarangay = new Map();
        const profileDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        let totalProcessedDocs = 0;
        const BATCH_SIZE = 10000; // Firestore max limit is 10000

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          totalProcessedDocs += snapshot.docs.length;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            
            // Only process voters with VotingStatus = "VOTER"
            const votingStatus = (voter.VotingStatus || "").toUpperCase().trim();
            if (votingStatus !== "VOTER") {
              return; // Skip non-voters
            }
            
            let barangay = voter.ProfiledBarangay || "";
            barangay = String(barangay).trim();
            
            let purok = voter.ProfiledPurok || "";
            purok = String(purok).trim();

            // Only process if both barangay and purok have values
            if (barangay && barangay !== "" && purok && purok !== "") {
              // Add to barangays set
              barangaysSet.add(barangay);

              // Track puroks per barangay
              if (!puroksByBarangay.has(barangay)) {
                puroksByBarangay.set(barangay, new Set());
              }
              puroksByBarangay.get(barangay).add(purok);

              // Create key for profile data map
              const key = `${barangay}_${purok}`;

              // Initialize profile data if not exists
              if (!profileDataMap.has(key)) {
                profileDataMap.set(key, {
                  barangay: barangay,
                  purok: purok,
                  PROFILE: 0,
                  ADMIN: 0,
                  OPPOSITION: 0,
                  "NO STATUS": 0,
                });
              }

              // Count political status - skip NON-VOTER and UNTAGGED
              const status = (voter.PoliticalStatus || "").toUpperCase().trim();
              
              // Skip NON-VOTER and UNTAGGED records
              if (status === "NON-VOTER" || status === "UNTAGGED" || status === "") {
                return; // Skip this record
              }
              
              const currentData = profileDataMap.get(key);

              switch (status) {
                case "ADMIN":
                  currentData.ADMIN += 1;
                  break;
                case "OPPOSITION":
                  currentData.OPPOSITION += 1;
                  break;
                case "NO STATUS":
                case "NO_STATUS":
                  currentData["NO STATUS"] += 1;
                  break;
                default:
                  // Skip other statuses
                  break;
              }
            }
          });

          // Update progress: 0-80% for fetching phase
          const fetchProgress = Math.min(80, Math.floor((totalProcessedDocs / 1000) * 5));
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        // Aggregation phase: 80-90%
        setLoadingProgress(85);
        
        // Process aggregated data
        const aggregatedData = Array.from(profileDataMap.values()).map(row => ({
          ...row,
          PROFILE: row.ADMIN + row.OPPOSITION + row["NO STATUS"],
          TOTAL: row.ADMIN + row.OPPOSITION + row["NO STATUS"]
        }));

        aggregatedData.sort((a, b) => {
          if (a.barangay !== b.barangay) {
            return a.barangay.localeCompare(b.barangay);
          }
          return a.purok.localeCompare(b.purok);
        });

        // Preparation phase: 90-99%
        setLoadingProgress(95);

        // Set barangays and table data
        const barangays = Array.from(barangaysSet).sort();
        setAllBarangays(barangays);
        setSelectedBarangays(barangays); // Start with all barangays selected by default
        setAllTableData(aggregatedData);
        
        // Cache data to localStorage
        try {
          localStorage.setItem("profileAddressData", JSON.stringify({
            barangays: barangays,
            tableData: aggregatedData
          }));
        } catch (err) {
          console.warn("Failed to cache data:", err);
        }
        
        // Data ready to display: 100%
        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllBarangays([]);
        setAllTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchAllData();
  }, []);

  // Update puroks when barangay selection changes
  useEffect(() => {
    if (selectedBarangays.length === 0) {
      setAllPuroks([]);
      setSelectedPuroks([]);
      return;
    }

    // Get unique puroks for selected barangays
    const puroksSet = new Set();
    allTableData.forEach((row) => {
      if (selectedBarangays.includes(row.barangay)) {
        puroksSet.add(row.purok);
      }
    });

    const puroks = Array.from(puroksSet).sort();
    setAllPuroks(puroks);
    setSelectedPuroks([]); // Don't auto-select puroks, let user choose
  }, [selectedBarangays, allTableData]);

  const handleBarangayChange = (value) => {
    if (value.includes("SELECT_ALL_BARANGAY")) {
      if (selectedBarangays.length === allBarangays.length) {
        setSelectedBarangays([]);
      } else {
        setSelectedBarangays(allBarangays);
      }
    } else {
      setSelectedBarangays(value);
    }
  };

  const handlePurokChange = (value) => {
    if (value.includes("SELECT_ALL_PUROK")) {
      if (selectedPuroks.length === allPuroks.length) {
        setSelectedPuroks([]);
      } else {
        setSelectedPuroks(allPuroks);
      }
    } else {
      setSelectedPuroks(value);
    }
  };

  const handleColumnToggle = (column) => {
    setSelectedColumns((prev) => ({
      ...prev,
      [column]: !prev[column],
    }));
  };

  const handleRefreshData = () => {
    // Clear cache and refetch data without reloading page
    localStorage.removeItem("profileAddressData");
    
    const fetchFreshData = async () => {
      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const puroksByBarangay = new Map();
        const profileDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 10000;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            
            const votingStatus = (voter.VotingStatus || "").toUpperCase().trim();
            if (votingStatus !== "VOTER") {
              return;
            }
            
            let barangay = voter.ProfiledBarangay || "";
            barangay = String(barangay).trim();
            
            let purok = voter.ProfiledPurok || "";
            purok = String(purok).trim();

            if (barangay && barangay !== "" && purok && purok !== "") {
              barangaysSet.add(barangay);

              if (!puroksByBarangay.has(barangay)) {
                puroksByBarangay.set(barangay, new Set());
              }
              puroksByBarangay.get(barangay).add(purok);

              const key = `${barangay}_${purok}`;

              if (!profileDataMap.has(key)) {
                profileDataMap.set(key, {
                  barangay: barangay,
                  purok: purok,
                  PROFILE: 0,
                  ADMIN: 0,
                  OPPOSITION: 0,
                  "NO STATUS": 0,
                });
              }

              const politicalStatus = (voter.PoliticalStatus || "NO_STATUS").toUpperCase().trim();
              const profileStatus = profileDataMap.get(key);

              switch (politicalStatus) {
                case "PROFILE":
                  profileStatus.PROFILE += 1;
                  break;
                case "ADMIN":
                  profileStatus.ADMIN += 1;
                  break;
                case "OPPOSITION":
                  profileStatus.OPPOSITION += 1;
                  break;
                default:
                  profileStatus["NO STATUS"] += 1;
              }
            }
          });

          setLoadingProgress(Math.min(80, Math.floor((snapshot.docs.length / 1000) * 5)));

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(85);

        const aggregatedData = Array.from(profileDataMap.values()).map((row) => ({
          ...row,
          TOTAL: row.PROFILE + row.ADMIN + row.OPPOSITION + row["NO STATUS"],
        }));

        aggregatedData.sort((a, b) => {
          if (a.barangay === b.barangay) {
            return a.purok.localeCompare(b.purok);
          }
          return a.barangay.localeCompare(b.barangay);
        });

        setLoadingProgress(95);

        const barangays = Array.from(barangaysSet).sort();
        setAllBarangays(barangays);
        setSelectedBarangays(barangays);
        setAllTableData(aggregatedData);

        try {
          localStorage.setItem(
            "profileAddressData",
            JSON.stringify({
              barangays: barangays,
              tableData: aggregatedData,
              timestamp: Date.now(),
            })
          );
        } catch (err) {
          console.warn("Failed to cache data:", err);
        }

        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllBarangays([]);
        setAllTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchFreshData();
  };

  // Get filtered data based on selected barangays and puroks
  const filteredTableData = useMemo(() => {
    // If no barangays selected, show nothing
    if (selectedBarangays.length === 0) {
      return [];
    }

    // If all barangays selected and no puroks selected, show aggregated barangay data
    if (selectedBarangays.length === allBarangays.length && selectedPuroks.length === 0) {
      const barangayMap = new Map();
      allTableData.forEach((row) => {
        if (!barangayMap.has(row.barangay)) {
          barangayMap.set(row.barangay, {
            barangay: row.barangay,
            purok: "",
            PROFILE: 0,
            ADMIN: 0,
            OPPOSITION: 0,
            "NO STATUS": 0,
            TOTAL: 0,
          });
        }
        const barangayData = barangayMap.get(row.barangay);
        barangayData.PROFILE += row.PROFILE;
        barangayData.ADMIN += row.ADMIN;
        barangayData.OPPOSITION += row.OPPOSITION;
        barangayData["NO STATUS"] += row["NO STATUS"];
        barangayData.TOTAL += row.TOTAL;
      });
      return Array.from(barangayMap.values());
    }

    // If specific barangays selected with puroks, show detailed data
    if (selectedPuroks.length > 0) {
      return allTableData.filter(row => 
        selectedBarangays.includes(row.barangay) && 
        selectedPuroks.includes(row.purok)
      );
    }

    // If specific barangays selected without puroks, show aggregated data for those barangays
    const barangayMap = new Map();
    allTableData.forEach((row) => {
      if (selectedBarangays.includes(row.barangay)) {
        if (!barangayMap.has(row.barangay)) {
          barangayMap.set(row.barangay, {
            barangay: row.barangay,
            purok: "",
            PROFILE: 0,
            ADMIN: 0,
            OPPOSITION: 0,
            "NO STATUS": 0,
            TOTAL: 0,
          });
        }
        const barangayData = barangayMap.get(row.barangay);
        barangayData.PROFILE += row.PROFILE;
        barangayData.ADMIN += row.ADMIN;
        barangayData.OPPOSITION += row.OPPOSITION;
        barangayData["NO STATUS"] += row["NO STATUS"];
        barangayData.TOTAL += row.TOTAL;
      }
    });
    return Array.from(barangayMap.values());
  }, [selectedBarangays, selectedPuroks, allTableData, allBarangays.length]);

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    const tableData = filteredTableData.map(row => [
      row.barangay,
      row.purok,
      selectedColumns.PROFILE ? row.PROFILE.toLocaleString() : "-",
      selectedColumns.ADMIN ? row.ADMIN.toLocaleString() : "-",
      selectedColumns.OPPOSITION ? row.OPPOSITION.toLocaleString() : "-",
      selectedColumns["NO STATUS"] ? row["NO STATUS"].toLocaleString() : "-",
      row.TOTAL.toLocaleString(),
    ]);

    const headers = ["BARANGAY", "PUROK"];
    if (selectedColumns.PROFILE) headers.push("PROFILE");
    if (selectedColumns.ADMIN) headers.push("ADMIN");
    if (selectedColumns.OPPOSITION) headers.push("OPPOSITION");
    if (selectedColumns["NO STATUS"]) headers.push("NO STATUS");
    headers.push("TOTAL");

    const totals = filteredTableData.reduce((sum, row) => {
      const profile = selectedColumns.PROFILE ? row.PROFILE : 0;
      const admin = selectedColumns.ADMIN ? row.ADMIN : 0;
      const opposition = selectedColumns.OPPOSITION ? row.OPPOSITION : 0;
      const noStatus = selectedColumns["NO STATUS"] ? row["NO STATUS"] : 0;
      return {
        profile: sum.profile + profile,
        admin: sum.admin + admin,
        opposition: sum.opposition + opposition,
        noStatus: sum.noStatus + noStatus,
      };
    }, { profile: 0, admin: 0, opposition: 0, noStatus: 0 });

    tableData.push([
      "TOTAL",
      "",
      selectedColumns.PROFILE ? totals.profile.toLocaleString() : "-",
      selectedColumns.ADMIN ? totals.admin.toLocaleString() : "-",
      selectedColumns.OPPOSITION ? totals.opposition.toLocaleString() : "-",
      selectedColumns["NO STATUS"] ? totals.noStatus.toLocaleString() : "-",
      totals.profile.toLocaleString(),
    ]);

    doc.text("Profile Address Report", 14, 10);
    autoTable(doc, {
      head: [headers],
      body: tableData,
      startY: 20,
      theme: "grid",
      headStyles: { fillColor: [26, 35, 126], textColor: 255, fontStyle: "bold" },
    });

    doc.save("Profile_Address_Report.pdf");
  };

  // Export to Excel
  const exportToExcel = () => {
    const exportData = filteredTableData.map(row => ({
      BARANGAY: row.barangay,
      PUROK: row.purok,
      ...(selectedColumns.PROFILE && { PROFILE: row.PROFILE }),
      ...(selectedColumns.ADMIN && { ADMIN: row.ADMIN }),
      ...(selectedColumns.OPPOSITION && { OPPOSITION: row.OPPOSITION }),
      ...(selectedColumns["NO STATUS"] && { "NO STATUS": row["NO STATUS"] }),
      TOTAL: row.PROFILE,
    }));

    const totals = filteredTableData.reduce((sum, row) => {
      const profile = selectedColumns.PROFILE ? row.PROFILE : 0;
      const admin = selectedColumns.ADMIN ? row.ADMIN : 0;
      const opposition = selectedColumns.OPPOSITION ? row.OPPOSITION : 0;
      const noStatus = selectedColumns["NO STATUS"] ? row["NO STATUS"] : 0;
      return {
        profile: sum.profile + profile,
        admin: sum.admin + admin,
        opposition: sum.opposition + opposition,
        noStatus: sum.noStatus + noStatus,
      };
    }, { profile: 0, admin: 0, opposition: 0, noStatus: 0 });

    exportData.push({
      BARANGAY: "TOTAL",
      PUROK: "",
      ...(selectedColumns.PROFILE && { PROFILE: totals.profile }),
      ...(selectedColumns.ADMIN && { ADMIN: totals.admin }),
      ...(selectedColumns.OPPOSITION && { OPPOSITION: totals.opposition }),
      ...(selectedColumns["NO STATUS"] && { "NO STATUS": totals.noStatus }),
      TOTAL: totals.profile,
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Profile Address");
    XLSX.writeFile(wb, "Profile_Address_Report.xlsx");
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box
        sx={{
          flexGrow: 1,
          width: { xs: "100%", md: "calc(100% - 260px)" },
          display: "flex",
          flexDirection: "column",
          minHeight: "100vh",
        }}
      >
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 2, overflowX: "auto" }}>
          {/* Advanced Settings Component */}
          <ProfileAdvancedSettings
            advancedOpen={advancedOpen}
            setAdvancedOpen={setAdvancedOpen}
            selectedColumns={selectedColumns}
            handleColumnToggle={handleColumnToggle}
            allBarangays={allBarangays}
            selectedBarangays={selectedBarangays}
            handleBarangayChange={handleBarangayChange}
            allPuroks={allPuroks}
            selectedPuroks={selectedPuroks}
            handlePurokChange={handlePurokChange}
          />
          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Profile Address Report
              </Typography>
              <Typography variant="caption" sx={{ color: "#666", mt: 0.5, display: "block" }}>
                Political Status Distribution by Barangay and Purok
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button
                startIcon={<Refresh />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handleRefreshData}
              >
                Refresh Data
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToPDF}
              >
                Export PDF
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToExcel}
              >
                Export Excel
              </Button>
              <Button
                startIcon={<Print />}
                variant="contained"
                color="success"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
              >
                Print Email
              </Button>
            </Box>
          </Box>

          {/* Table Component */}
          <ProfileAddressTable 
            selectedColumns={selectedColumns}
            selectedBarangays={selectedBarangays}
            selectedPuroks={selectedPuroks}
            allTableData={filteredTableData}
            loading={loading}
            loadingProgress={loadingProgress}
          />
        </Box>
      </Box>
    </Box>
  );
};

export default ProfileAddress;
