import React, { useState } from "react";
import {
  Box,
  Card,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  CircularProgress,
  IconButton,
} from "@mui/material";
import { Visibility as VisibilityIcon } from "@mui/icons-material";
import VotersViewDialog from "../dialogs/VotersViewDialog";

const spinAnimation = `
  @keyframes spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
`;

const ProfileAddressTable = ({ 
  selectedColumns = {}, 
  selectedBarangays = [],
  selectedPuroks = [],
  allTableData = [],
  loading = false,
  loadingProgress = 0
}) => {
  const tableHeaders = [
    { key: "barangay", label: "BARANGAY", bgColor: "#1a237e", textColor: "#fff" },
    { key: "purok", label: "PUROK", bgColor: "#1a237e", textColor: "#fff", show: selectedPuroks.length > 0 },
    { key: "PROFILE", label: "PROFILE", bgColor: "#6366f1", textColor: "#fff", show: selectedColumns.PROFILE !== false },
    { key: "ADMIN", label: "ADMIN", bgColor: "#3b82f6", textColor: "#fff", show: selectedColumns.ADMIN !== false },
    { key: "OPPOSITION", label: "OPPOSITION", bgColor: "#10b981", textColor: "#fff", show: selectedColumns.OPPOSITION !== false },
    { key: "NO STATUS", label: "NO STATUS", bgColor: "#f59e0b", textColor: "#fff", show: selectedColumns["NO STATUS"] !== false },
    { key: "TOTAL", label: "TOTAL", bgColor: "#1a237e", textColor: "#fff" },
    { key: "action", label: "ACTION", bgColor: "#1a237e", textColor: "#fff" },
  ];

  // Dialog state
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedRowData, setSelectedRowData] = useState(null);

  // Handle view button click
  const handleViewClick = (barangay, purok) => {
    setSelectedRowData({ barangay, purok });
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedRowData(null);
  };

  // Use the data as provided (already filtered by parent component)
  const filteredData = allTableData;

  // Calculate totals from filtered data
  const profileTotal = filteredData.reduce((sum, row) => sum + (row.PROFILE || 0), 0);
  const adminTotal = filteredData.reduce((sum, row) => sum + (row.ADMIN || 0), 0);
  const oppositionTotal = filteredData.reduce((sum, row) => sum + (row.OPPOSITION || 0), 0);
  const noStatusTotal = filteredData.reduce((sum, row) => sum + (row["NO STATUS"] || 0), 0);
  
  const totalRow = {
    barangay: "TOTAL",
    purok: "",
    PROFILE: profileTotal,
    ADMIN: adminTotal,
    OPPOSITION: oppositionTotal,
    "NO STATUS": noStatusTotal,
    TOTAL: profileTotal + adminTotal + oppositionTotal + noStatusTotal,
  };

  return (
    <Card sx={{ bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)", borderRadius: 1.5 }}>
      {loading ? (
        <Box
          sx={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            minHeight: 400,
            flexDirection: "column",
            gap: 2,
          }}
        >
          <style>{spinAnimation}</style>
          <Box sx={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <CircularProgress 
              size={80} 
              sx={{ 
                color: "#1f8ef1",
                animation: "spin 1s linear infinite"
              }} 
              variant="determinate"
              value={loadingProgress}
            />
            <Typography 
              variant="h6" 
              sx={{ 
                position: "absolute",
                color: "#1f8ef1", 
                fontWeight: 700,
                fontSize: 24
              }}
            >
              {loadingProgress}%
            </Typography>
          </Box>
          <Typography variant="caption" sx={{ color: "#1f8ef1", fontWeight: 600 }}>
            Loading profile data...
          </Typography>
        </Box>
      ) : (
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: "#1a237e" }}>
                {tableHeaders.map((header) => (
                  (!header.show && header.key !== "barangay" && header.key !== "purok" && header.key !== "TOTAL") ? null : (
                    <TableCell
                      key={header.key}
                      align={header.key === "barangay" || header.key === "purok" ? "left" : "center"}
                      sx={{
                        color: header.textColor,
                        fontWeight: 700,
                        fontSize: 13,
                        py: 2.5,
                        px: 2,
                        bgcolor: header.bgColor,
                        borderRight: "1px solid rgba(255, 255, 255, 0.1)",
                        "&:last-child": {
                          borderRight: "none",
                        },
                      }}
                    >
                      {header.label}
                    </TableCell>
                  )
                ))}
              </TableRow>
            </TableHead>

            <TableBody>
              {filteredData.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={tableHeaders.length} align="center" sx={{ py: 4 }}>
                    <Typography variant="body2" sx={{ color: "#999" }}>
                      No profile records found.
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                <>
                  {filteredData.map((row, idx) => (
                    <TableRow
                      key={idx}
                      hover
                      sx={{
                        "&:hover": { bgcolor: "#f8f9fa" },
                        transition: "background-color 0.2s ease",
                        borderBottom: "1px solid #e5e7eb",
                      }}
                    >
                      {tableHeaders.map((header) => (
                        (!header.show && header.key !== "barangay" && header.key !== "purok" && header.key !== "TOTAL" && header.key !== "action") ? null : (
                          <TableCell
                            key={header.key}
                            align={header.key === "barangay" || header.key === "purok" ? "left" : "center"}
                            sx={{
                              color: (header.key === "barangay" || header.key === "purok") ? "#1a237e" : "#333",
                              fontWeight: (header.key === "barangay" || header.key === "purok") ? 600 : 500,
                              fontSize: 13,
                              py: 2,
                              px: 2,
                            }}
                          >
                            {header.key === "action" ? (
                              <IconButton
                                size="small"
                                onClick={() => handleViewClick(row.barangay, row.purok)}
                                sx={{ color: "#135bec", "&:hover": { bgcolor: "#e8ecff" } }}
                              >
                                <VisibilityIcon fontSize="small" />
                              </IconButton>
                            ) : header.key === "barangay"
                              ? row.barangay
                              : header.key === "purok"
                              ? row.purok
                              : row[header.key]?.toLocaleString() || 0}
                          </TableCell>
                        )
                      ))}
                    </TableRow>
                  ))}

                  {/* Totals Row */}
                  <TableRow
                    sx={{
                      bgcolor: "#f0f4ff",
                      fontWeight: 700,
                      borderTop: "2px solid #1a237e",
                    }}
                  >
                    {tableHeaders.map((header) => (
                      (!header.show && header.key !== "barangay" && header.key !== "purok" && header.key !== "TOTAL") ? null : (
                        <TableCell
                          key={header.key}
                          align={header.key === "barangay" || header.key === "purok" ? "left" : "center"}
                          sx={{
                            fontWeight: 700,
                            color: "#1a237e",
                            fontSize: 13,
                            py: 2.5,
                            px: 2,
                            bgcolor: (header.key === "barangay" || header.key === "purok") ? "#f0f4ff" : "#e8ecff",
                          }}
                        >
                          {header.key === "barangay"
                            ? totalRow.barangay
                            : header.key === "purok"
                            ? totalRow.purok
                            : totalRow[header.key]?.toLocaleString() || 0}
                        </TableCell>
                      )
                    ))}
                  </TableRow>
                </>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {/* Voter Details Dialog */}
      <VotersViewDialog
        open={openDialog}
        onClose={handleCloseDialog}
        barangay={selectedRowData?.barangay}
        purok={selectedRowData?.purok}
      />
    </Card>
  );
};

export default ProfileAddressTable;
