import React, { useMemo } from "react";
import {
  Box,
  Card,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  CircularProgress,
} from "@mui/material";

const spinAnimation = `
  @keyframes spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
`;

const VotersAddressTable = ({ 
  selectedColumns = {}, 
  selectedVotersAddresses = [],
  allTableData = [],
  loading = false,
  loadingProgress = 0
}) => {
  const tableHeaders = [
    { key: "barangay", label: "BARANGAY", bgColor: "#1a237e", textColor: "#fff" },
    { key: "VOTER", label: "VOTER", bgColor: "#6366f1", textColor: "#fff", show: selectedColumns.VOTER !== false },
    { key: "ADMIN", label: "ADMIN", bgColor: "#3b82f6", textColor: "#fff", show: selectedColumns.ADMIN !== false },
    { key: "OPPOSITION", label: "OPPOSITION", bgColor: "#10b981", textColor: "#fff", show: selectedColumns.OPPOSITION !== false },
    { key: "NO STATUS", label: "NO STATUS", bgColor: "#f59e0b", textColor: "#fff", show: selectedColumns["NO STATUS"] !== false },
    { key: "UNTAGGED", label: "UNTAGGED", bgColor: "#ef4444", textColor: "#fff", show: selectedColumns.UNTAGGED !== false },
    { key: "TOTAL", label: "TOTAL", bgColor: "#1a237e", textColor: "#fff" },
  ];

  // Filter data based on selected barangays (instant realtime filtering)
  const filteredData = useMemo(() => {
    if (selectedVotersAddresses.length === 0) {
      return allTableData;
    }
    return allTableData.filter(row => 
      selectedVotersAddresses.includes(row.barangay)
    );
  }, [selectedVotersAddresses, allTableData]);

  // Calculate totals from filtered data
  const voterTotal = filteredData.reduce((sum, row) => sum + (row.VOTER || 0), 0);
  const totalRow = {
    barangay: "TOTAL",
    VOTER: voterTotal,
    ADMIN: filteredData.reduce((sum, row) => sum + (row.ADMIN || 0), 0),
    OPPOSITION: filteredData.reduce((sum, row) => sum + (row.OPPOSITION || 0), 0),
    "NO STATUS": filteredData.reduce((sum, row) => sum + (row["NO STATUS"] || 0), 0),
    UNTAGGED: filteredData.reduce((sum, row) => sum + (row.UNTAGGED || 0), 0),
    TOTAL: voterTotal, // TOTAL should equal VOTER count, not sum of all TOTAL values
  };

  return (
    <Card sx={{ bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)", borderRadius: 1.5 }}>
      {loading ? (
        <Box
          sx={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            minHeight: 400,
            flexDirection: "column",
            gap: 2,
          }}
        >
          <style>{spinAnimation}</style>
          <Box sx={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <CircularProgress 
              size={80} 
              sx={{ 
                color: "#1f8ef1",
                animation: "spin 1s linear infinite"
              }} 
              variant="determinate"
              value={loadingProgress}
            />
            <Typography 
              variant="h6" 
              sx={{ 
                position: "absolute",
                color: "#1f8ef1", 
                fontWeight: 700,
                fontSize: 24
              }}
            >
              {loadingProgress}%
            </Typography>
          </Box>
          <Typography variant="caption" sx={{ color: "#1f8ef1", fontWeight: 600 }}>
            Loading voters data...
          </Typography>
        </Box>
      ) : (
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: "#1a237e" }}>
                {tableHeaders.map((header) => (
                  (!header.show && header.key !== "barangay" && header.key !== "TOTAL") ? null : (
                    <TableCell
                      key={header.key}
                      align={header.key === "barangay" ? "left" : "center"}
                      sx={{
                        color: header.textColor,
                        fontWeight: 700,
                        fontSize: 13,
                        py: 2.5,
                        px: 2,
                        bgcolor: header.bgColor,
                        borderRight: "1px solid rgba(255, 255, 255, 0.1)",
                        "&:last-child": {
                          borderRight: "none",
                        },
                      }}
                    >
                      {header.label}
                    </TableCell>
                  )
                ))}
              </TableRow>
            </TableHead>

            <TableBody>
              {filteredData.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={tableHeaders.length} align="center" sx={{ py: 4 }}>
                    <Typography variant="body2" sx={{ color: "#999" }}>
                      No voter records found.
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                <>
                  {filteredData.map((row, idx) => (
                    <TableRow
                      key={idx}
                      hover
                      sx={{
                        "&:hover": { bgcolor: "#f8f9fa" },
                        transition: "background-color 0.2s ease",
                        borderBottom: "1px solid #e5e7eb",
                      }}
                    >
                      {tableHeaders.map((header) => (
                        (!header.show && header.key !== "barangay" && header.key !== "TOTAL") ? null : (
                          <TableCell
                            key={header.key}
                            align={header.key === "barangay" ? "left" : "center"}
                            sx={{
                              color: header.key === "barangay" ? "#1a237e" : "#333",
                              fontWeight: header.key === "barangay" ? 600 : 500,
                              fontSize: 13,
                              py: 2,
                              px: 2,
                            }}
                          >
                            {header.key === "barangay"
                              ? row.barangay
                              : row[header.key]?.toLocaleString() || 0}
                          </TableCell>
                        )
                      ))}
                    </TableRow>
                  ))}

                  {/* Totals Row */}
                  <TableRow
                    sx={{
                      bgcolor: "#f0f4ff",
                      fontWeight: 700,
                      borderTop: "2px solid #1a237e",
                    }}
                  >
                    {tableHeaders.map((header) => (
                      (!header.show && header.key !== "barangay" && header.key !== "TOTAL") ? null : (
                        <TableCell
                          key={header.key}
                          align={header.key === "barangay" ? "left" : "center"}
                          sx={{
                            fontWeight: 700,
                            color: "#1a237e",
                            fontSize: 13,
                            py: 2.5,
                            px: 2,
                            bgcolor: header.key === "barangay" ? "#f0f4ff" : "#e8ecff",
                          }}
                        >
                          {header.key === "barangay"
                            ? totalRow.barangay
                            : totalRow[header.key]?.toLocaleString() || 0}
                        </TableCell>
                      )
                    ))}
                  </TableRow>
                </>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Card>
  );
};

export default VotersAddressTable;
