// --- Memoized Input Component ---
const RowInput = React.memo(
  ({
    idx,
    value,
    header,
    options,
    isEditable,
    handleChange,
    invalid,
    showError,
    inputRefs,
    dependentOptions,
  }) => {
    const upperHeader = header.toUpperCase();
    const isRequired = REQUIRED_FIELDS.includes(upperHeader);
    const hasError = invalid || (isRequired && showError && !value?.trim());

    const commonProps = {
      fullWidth: true,
      label: header,
      value,
      onChange: (e) => handleChange(idx, e.target.value),
      sx: { mt: 1 },
      disabled: !isEditable,
      inputRef: (el) => (inputRefs.current[idx] = el),
      error: hasError,
      helperText: hasError
        ? invalid
          ? "Invalid value"
          : isRequired
          ? "Required"
          : ""
        : "",
      onKeyDown: (e) => {
        if (["ArrowDown", "Enter"].includes(e.key)) {
          e.preventDefault();
          if (inputRefs.current[idx + 1]) inputRefs.current[idx + 1].focus();
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          if (inputRefs.current[idx - 1]) inputRefs.current[idx - 1].focus();
        }
      },
    };

    // Timestamp is read-only
    if (upperHeader === "TIMESTAMP") {
      return <TextField key={idx} {...commonProps} disabled />;
    }

    // Encoder column is hidden
    if (upperHeader === "ENCODER") return null;

    // Autocomplete with dependent options (PUROK)
    if (upperHeader === "PUROK") {
      return (
        <Autocomplete
          key={idx}
          options={dependentOptions || []}
          value={value || null}
          disableClearable
          autoHighlight
          onChange={(e, newValue) => handleChange(idx, newValue || "")}
          onInputChange={(e, newInputValue) =>
            handleChange(idx, newInputValue || "")
          }
          renderInput={(params) => <TextField {...params} {...commonProps} />}
        />
      );
    }

    // Standard Autocomplete
    if (options?.length) {
      return (
        <Autocomplete
          key={idx}
          options={options}
          value={value || null}
          disableClearable
          autoHighlight
          onChange={(e, newValue) => handleChange(idx, newValue || "")}
          onInputChange={(e, newInputValue) =>
            handleChange(idx, newInputValue || "")
          }
          renderInput={(params) => <TextField {...params} {...commonProps} />}
        />
      );
    }

    // Default TextField
    return <TextField key={idx} {...commonProps} />;
  }
);

