// src/components/EncodingSidebar.jsx
import React, { useState, useEffect } from "react";
import {
  Box,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Toolbar,
  Divider,
  IconButton,
  Tooltip,
  Avatar,
  Collapse,
  alpha,
} from "@mui/material";
import { useLocation, useNavigate } from "react-router-dom";
import MenuIcon from "@mui/icons-material/Menu";
import HomeIcon from "@mui/icons-material/Home";
import PaymentIcon from "@mui/icons-material/Payment";
import AssignmentIcon from "@mui/icons-material/Assignment";
import UploadFileIcon from "@mui/icons-material/UploadFile";
import MonitoringIcon from "@mui/icons-material/MonitorHeart";
import SettingsIcon from "@mui/icons-material/Settings";
import LogoutIcon from "@mui/icons-material/Logout";
import ExpandMore from "@mui/icons-material/ExpandMore";
import PeopleIcon from "@mui/icons-material/People";
import { usersDB } from "../db/usersDB";

const drawerWidth = 265;
const collapsedWidth = 90;

const EncodingSidebar = ({ collapsed: collapsedProp = false, onToggle }) => {
  const location = useLocation();
  const navigate = useNavigate();

  const [collapsed, setCollapsed] = useState(collapsedProp);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [avatar, setAvatar] = useState(null);
  const [monitoringOpen, setMonitoringOpen] = useState(true);
  const [dataManagementOpen, setDataManagementOpen] = useState(true);

  const name = localStorage.getItem("name") || "Encoder";
  const role = localStorage.getItem("role") || "encoder";
  const username = localStorage.getItem("username");

  // Load avatar from Dexie DB on mount
  useEffect(() => {
     const loadAvatar = async () => {
    console.log("[EncodingSidebar] Loading avatar for username:", username);
    if (!username) {
      console.log("[EncodingSidebar] No username found in localStorage");
      return;
    }

    try {
      const user = await usersDB.users.where("username").equals(username).first();
      console.log("[EncodingSidebar] Dexie user fetched:", user);
      if (user?.avatar) {
        setAvatar(user.avatar);
        console.log("[EncodingSidebar] Avatar set from Dexie");
      } else {
        console.log("[EncodingSidebar] No avatar found in Dexie");
      }
    } catch (err) {
      console.error("[EncodingSidebar] Error loading avatar from Dexie:", err);
    }
  };

  loadAvatar();
}, [username]);

  useEffect(() => {
    const pathMap = {
      "/home": 0,
      "/admin/user-management": 1,
      "/admin/tasks": 2,
      "/admin/payout-monitoring": 3,
      "/encoding/admin/import-tasks": 4,
      "/admin/payouts-offline": 5,
      "/settings": 6,
      "/encoder/encoding-task": 7,
      "/encoder/payout-task": 8,
    };
    const index = pathMap[location.pathname];
    if (index !== undefined) setSelectedIndex(index);
  }, [location.pathname]);

  const toggleCollapse = () => {
    setCollapsed(!collapsed);
    if (onToggle) onToggle(!collapsed);
  };

  const handleNavigate = (index, path) => {
    setSelectedIndex(index);
    if (path === "/logout") {
      localStorage.clear();
      return navigate("/login", { replace: true });
    }
    navigate(path);
  };

  const handleAvatarUpload = async (e) => {
  const file = e.target.files[0];
  console.log("[EncodingSidebar] Avatar file selected:", file);
  if (!file) return;
  if (!username) {
    console.log("[EncodingSidebar] No username, cannot save avatar");
    return;
  }

  const reader = new FileReader();
  reader.onload = async () => {
    const avatarData = reader.result;
    console.log("[EncodingSidebar] FileReader loaded avatar data:", avatarData?.slice(0, 50) + "..."); // log first 50 chars
    setAvatar(avatarData);

    try {
      // Check if user exists
      const user = await usersDB.users.where("username").equals(username).first();
      console.log("[EncodingSidebar] User fetched for update:", user);
      if (user) {
        await usersDB.users.where("username").equals(username).modify({ avatar: avatarData });
        console.log("[EncodingSidebar] Avatar updated in Dexie");
      } else {
        await usersDB.users.add({ username, avatar: avatarData, name, role });
        console.log("[EncodingSidebar] New user added with avatar in Dexie");
      }
    } catch (err) {
      console.error("[EncodingSidebar] Error saving avatar to Dexie:", err);
    }

    // Dispatch event
    console.log("[EncodingSidebar] Dispatching avatarChanged event");
    window.dispatchEvent(new CustomEvent("avatarChanged", { detail: avatarData }));
  };

  reader.onerror = (err) => {
    console.error("[EncodingSidebar] FileReader error:", err);
  };

  reader.readAsDataURL(file);
};

  const renderDropdownButton = (title, openState, toggleFunc) => (
    <Tooltip title={collapsed ? title : ""} placement="right" arrow>
      <ListItemButton
        onClick={toggleFunc}
        sx={{
          justifyContent: collapsed ? "center" : "flex-start",
          position: "relative",
          borderRadius: 2,
          "&:hover": { bgcolor: alpha("#fff", 0.15) },
          transition: "background 0.25s, transform 0.25s",
        }}
      >
        {!collapsed && <ListItemText primary={title} sx={{ ml: 2, fontWeight: 500 }} />}
        <Box
          sx={{
            position: "absolute",
            right: collapsed ? "50%" : 16,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `rotate(${openState ? 90 : 0}deg) translateY(${openState ? "1px" : "0"})`,
            transformOrigin: "center",
            transition: "transform 0.3s ease-in-out",
            color: "#fff",
          }}
        >
          <ExpandMore />
        </Box>
      </ListItemButton>
    </Tooltip>
  );

  const listItemStyle = {
    borderRadius: 4,
    "&:hover": { bgcolor: alpha("#fff", 0.15) },
    transition: "background 0.25s, transform 0.25s",
  };

  return (
    <Drawer
      variant="permanent"
      sx={{
        width: collapsed ? collapsedWidth : drawerWidth,
        flexShrink: 0,
        "& .MuiDrawer-paper": {
          width: collapsed ? collapsedWidth : drawerWidth,
          bgcolor: alpha("#446683", 0.85),
          backdropFilter: "blur(10px)",
          color: "#fff",
          transition: "width 0.3s",
        },
      }}
    >
      <Toolbar
        sx={{
          display: "flex",
          justifyContent: collapsed ? "center" : "space-between",
          alignItems: "center",
        }}
      >
        {!collapsed && (
          <Typography variant="h5" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
            SPM
            <Typography variant="caption" display="block" sx={{ fontWeight: 500 }}>
              Special Program Management
            </Typography>
          </Typography>
        )}
        <IconButton onClick={toggleCollapse} sx={{ color: "#fff" }}>
          <MenuIcon />
        </IconButton>
      </Toolbar>

      <Divider sx={{ bgcolor: alpha("#fff", 0.3) }} />

      <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", py: 3 }}>
        <input
          accept="image/*"
          type="file"
          id="avatar-upload"
          style={{ display: "none" }}
          onChange={handleAvatarUpload}
        />
        <label htmlFor="avatar-upload">
          <Avatar
            src={avatar}
            sx={{
              width: collapsed ? 45 : 85,
              height: collapsed ? 45 : 85,
              cursor: "pointer",
              transition: "all 0.25s ease",
              boxShadow: "0 4px 12px rgba(0,0,0,0.25)",
              "&:hover": { transform: "scale(1.08)" },
            }}
          />
        </label>
        {!collapsed && (
          <Typography variant="subtitle1" sx={{ mt: 1, fontWeight: 700, textAlign: "center" }}>
            {name}
          </Typography>
        )}
      </Box>

      <Box sx={{ flex: 1, overflowY: "auto", py: 1, "&::-webkit-scrollbar": { width: 0 }, scrollbarWidth: "none" }}>
        <List>
          <Tooltip title={collapsed ? "Home" : ""} placement="right" arrow>
          <ListItemButton
            selected={selectedIndex === 0}
            onClick={() => handleNavigate(0, "/home")} // <-- updated path
            sx={{ ...listItemStyle, justifyContent: collapsed ? "center" : "flex-start" }}
          >
            <ListItemIcon sx={{ color: "#fff", minWidth: 0, justifyContent: "center" }}>
              <HomeIcon />
            </ListItemIcon>
            {!collapsed && <ListItemText primary="Home" sx={{ ml: 2 }} />}
          </ListItemButton>
        </Tooltip>

         {/* Only show Encoding and Payout Task if NOT admin */}
        {role !== "admin" && (
          <>
            {/* Encoding Task link */}
            <Tooltip title={collapsed ? "Encoding Task" : ""} placement="right" arrow>
              <ListItemButton
                sx={{ ...listItemStyle, pl: 4 }}
                onClick={() => handleNavigate(8, "/encoder/encoding-task")}
              >
                <ListItemIcon sx={{ color: "#fff" }}>
                  <AssignmentIcon />
                </ListItemIcon>
                {!collapsed && <ListItemText primary="Encoding Task" />}
              </ListItemButton>
            </Tooltip>

            {/* Payout Task link */}
            <Tooltip title={collapsed ? "Payout Task" : ""} placement="right" arrow>
              <ListItemButton
                sx={{ ...listItemStyle, pl: 4 }}
                onClick={() => handleNavigate(8, "/encoder/payout-task")}
              >
                <ListItemIcon sx={{ color: "#fff" }}>
                  <AssignmentIcon />
                </ListItemIcon>
                {!collapsed && <ListItemText primary="Payout Task" />}
              </ListItemButton>
            </Tooltip>
          </>
        )}

          {role === "admin" && (
            <Tooltip title={collapsed ? "User Management" : ""} placement="right" arrow>
              <ListItemButton
                selected={selectedIndex === 1}
                onClick={() => handleNavigate(1, "/admin/user-management")}
                sx={{ ...listItemStyle, justifyContent: collapsed ? "center" : "flex-start" }}
              >
                <ListItemIcon sx={{ minWidth: 0, color: "#fff", justifyContent: "center" }}>
                  <PeopleIcon />
                </ListItemIcon>
                {!collapsed && <ListItemText primary="User Management" sx={{ ml: 2 }} />}
              </ListItemButton>
            </Tooltip>
          )}

          {role === "admin" && (
            <>
              {renderDropdownButton("Monitoring", monitoringOpen, () => setMonitoringOpen(!monitoringOpen))}
              <Collapse in={monitoringOpen} timeout="auto" unmountOnExit>
                <List component="div" disablePadding>
                  <Tooltip title={collapsed ? "Tasks" : ""} placement="right" arrow>
                    <ListItemButton sx={{ ...listItemStyle, pl: 4 }} onClick={() => handleNavigate(2, "/admin/tasks")}>
                      <ListItemIcon sx={{ color: "#fff" }}>
                        <AssignmentIcon />
                      </ListItemIcon>
                      {!collapsed && <ListItemText primary="Tasks" />}
                    </ListItemButton>
                  </Tooltip>
                  <Tooltip title={collapsed ? "Payout Monitoring" : ""} placement="right" arrow>
                    <ListItemButton sx={{ ...listItemStyle, pl: 4 }} onClick={() => handleNavigate(3, "/admin/payout-monitoring")}>
                      <ListItemIcon sx={{ color: "#fff" }}>
                        <MonitoringIcon />
                      </ListItemIcon>
                      {!collapsed && <ListItemText primary="Payout Monitoring" />}
                    </ListItemButton>
                  </Tooltip>
                </List>
              </Collapse>

              {renderDropdownButton("Data Management", dataManagementOpen, () => setDataManagementOpen(!dataManagementOpen))}
              <Collapse in={dataManagementOpen} timeout="auto" unmountOnExit>
                <List component="div" disablePadding>
                  <Tooltip title={collapsed ? "Import Tasks" : ""} placement="right" arrow>
                    <ListItemButton sx={{ ...listItemStyle, pl: 4 }} onClick={() => handleNavigate(4, "/encoding/admin/import-tasks")}>
                      <ListItemIcon sx={{ color: "#fff" }}>
                        <UploadFileIcon />
                      </ListItemIcon>
                      {!collapsed && <ListItemText primary="Import Tasks" />}
                    </ListItemButton>
                  </Tooltip>

                  <Tooltip title={collapsed ? "Payout Management" : ""} placement="right" arrow>
                    <ListItemButton sx={{ ...listItemStyle, pl: 4 }} onClick={() => handleNavigate(5, "/admin/payouts-offline")}>
                      <ListItemIcon sx={{ color: "#fff" }}>
                        <PaymentIcon />
                      </ListItemIcon>
                      {!collapsed && <ListItemText primary="Payout Management" />}
                    </ListItemButton>
                  </Tooltip>
                </List>
              </Collapse>
            </>
          )}

          <Tooltip title={collapsed ? "Settings" : ""} placement="right" arrow>
            <ListItemButton
              selected={selectedIndex === 6}
              onClick={() => handleNavigate(6, "/settings")}
              sx={{ ...listItemStyle, justifyContent: collapsed ? "center" : "flex-start" }}
            >
              <ListItemIcon sx={{ minWidth: 0, color: "#fff", justifyContent: "center" }}>
                <SettingsIcon />
              </ListItemIcon>
              {!collapsed && <ListItemText primary="Settings" sx={{ ml: 2 }} />}
            </ListItemButton>
          </Tooltip>

          <Tooltip title={collapsed ? "Logout" : ""} placement="right" arrow>
            <ListItemButton
              onClick={() => handleNavigate(7, "/logout")}
              sx={{ ...listItemStyle, justifyContent: collapsed ? "center" : "flex-start" }}
            >
              <ListItemIcon sx={{ minWidth: 0, color: "#fff", justifyContent: "center" }}>
                <LogoutIcon />
              </ListItemIcon>
              {!collapsed && <ListItemText primary="Logout" sx={{ ml: 2 }} />}
            </ListItemButton>
          </Tooltip>
        </List>
      </Box>

      <Box sx={{ py: 1, textAlign: "center", bgcolor: alpha("#000", 0.2) }}>
        <Typography variant="caption">All rights reserved ©2025</Typography>
      </Box>
    </Drawer>
  );
};

export default EncodingSidebar;