// src/pages/admin/AdminPayoutMonitoring.jsx
import React, { useState, useEffect, useMemo, useRef } from "react";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Divider,
  TextField,
  MenuItem,
  Stack,
  Button,
  Chip,
  useMediaQuery,
  useTheme,
  Drawer,
  IconButton,
  Avatar,
  InputAdornment,
  Checkbox
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import MenuIcon from "@mui/icons-material/Menu";
import EncodingSidebar from "../../components/EncodingSidebar";
import io from "socket.io-client";
import * as XLSX from "xlsx";
import FileDownloadIcon from "@mui/icons-material/FileDownload";

const SERVER_URL = "http://192.168.0.149:4000";;
const ROWS_PER_PAGE = 25;

const AdminPayoutMonitoring = () => {
  const [importedFiles, setImportedFiles] = useState([]);
  const [selectedPayout, setSelectedPayout] = useState(null);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [serverTime, setServerTime] = useState(new Date());
  const [connectionStatus, setConnectionStatus] = useState("Connecting...");
  const [heartbeatOn, setHeartbeatOn] = useState(false);

  const [visibleColumns, setVisibleColumns] = useState([]); // column visibility

  // Columns derived from payout data
const columns = useMemo(() => {
  if (!selectedPayout?.rows?.length) return [];
  return Object.keys(selectedPayout.rows[0]);
}, [selectedPayout]);

// Load visibleColumns from localStorage or default to all columns
useEffect(() => {
  const saved = localStorage.getItem("adminVisibleColumns");
  if (saved) {
    const parsed = JSON.parse(saved);
    const valid = columns.filter((c) => parsed.includes(c));
    setVisibleColumns(valid.length ? valid : columns);
  } else if (columns.length > 0) {
    setVisibleColumns(columns);
  }
}, [columns]);

// Save visibleColumns whenever it changes
useEffect(() => {
  localStorage.setItem("adminVisibleColumns", JSON.stringify(visibleColumns));
}, [visibleColumns]);

  const socketRef = useRef(null);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery(theme.breakpoints.between("sm", "md"));

  const drawerWidth = 265;
  const collapsedWidth = 60;
  const mainContentWidth = isMobile
    ? "100%"
    : `calc(100% - ${sidebarCollapsed ? collapsedWidth : drawerWidth}px)`;

  // ------------------- Server Time -------------------
  useEffect(() => {
    const interval = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  // ------------------- Fetch imported files list -------------------
  useEffect(() => {
    const fetchImportedFiles = async () => {
      try {
        const res = await fetch(`${SERVER_URL}/getImportedFiles`);
        const files = await res.json();
        setImportedFiles(files || []);
        if (files.length > 0) fetchPayoutData(files[0].name); // load first file
      } catch (err) {
        console.error("Failed to fetch imported files:", err);
        alert("⚠️ Cannot fetch imported files from server.");
      }
    };
    fetchImportedFiles();
  }, []);

  // ------------------- Fetch selected payout data -------------------
  const fetchPayoutData = async (fileName, clearView = true) => {
    try {
      const res = await fetch(`${SERVER_URL}/getPayouts`);
      const payouts = await res.json();
      const fileData = payouts.find((p) => p.fileName === fileName);
      if (fileData) {
        setSelectedPayout(fileData);
        if (clearView) {
          setSearch("");
          setPage(1);
        }
      }
    } catch (err) {
      console.error("Failed to fetch payout data:", err);
    }
  };

  // ------------------- Socket -------------------
  useEffect(() => {
    socketRef.current = io(SERVER_URL, {
      reconnectionAttempts: 5,
      transports: ["websocket"],
    });

    socketRef.current.on("connect", () => setConnectionStatus("Connected"));
    socketRef.current.on("disconnect", () => setConnectionStatus("Disconnected"));
    socketRef.current.on("reconnect_attempt", () => setConnectionStatus("Reconnecting..."));
    socketRef.current.on("reconnect_failed", () => setConnectionStatus("Failed to reconnect"));

    socketRef.current.on("payoutsUpdated", (updatedFiles) => {
      setImportedFiles(updatedFiles);

      // If we don't yet have a selected payout, pick the first available (tolerant to either string or object shapes)
      if (!selectedPayout && updatedFiles.length > 0) {
        const first = updatedFiles[0]?.fileName || updatedFiles[0]?.name || updatedFiles[0];
        if (first) fetchPayoutData(first, true);
      }

      // If the currently selected payout was updated, refresh its rows without clearing user's search/page
      if (selectedPayout?.fileName) {
        const contains = Array.isArray(updatedFiles)
          ? updatedFiles.includes(selectedPayout.fileName) || updatedFiles.some(u => (u?.fileName === selectedPayout.fileName) || (u?.name === selectedPayout.fileName))
          : false;

        if (contains) fetchPayoutData(selectedPayout.fileName, false);
      }
    });

    return () => socketRef.current.disconnect();
  }, [selectedPayout]);

  // ------------------- Heartbeat -------------------
  useEffect(() => {
    if (connectionStatus === "Connected") {
      const interval = setInterval(() => setHeartbeatOn((prev) => !prev), 500);
      return () => clearInterval(interval);
    } else {
      setHeartbeatOn(false);
    }
  }, [connectionStatus]);

  // ------------------- Filtered rows -------------------
  const filteredRows = useMemo(() => {
    if (!selectedPayout?.rows) return [];
    return selectedPayout.rows.filter((row) => {
      if (!search.trim()) return true;
      const lowerSearch = search.toLowerCase();
      return Object.values(row).some((val) =>
        String(val).toLowerCase().includes(lowerSearch)
      );
    });
  }, [selectedPayout, search]);

  // ------------------- Pagination -------------------
  const totalPages = Math.max(1, Math.ceil(filteredRows.length / ROWS_PER_PAGE));
  const paginatedRows = useMemo(() => {
    const start = (page - 1) * ROWS_PER_PAGE;
    return filteredRows.slice(start, start + ROWS_PER_PAGE);
  }, [filteredRows, page]);

  useEffect(() => {
    if (page > totalPages) setPage(1);
  }, [totalPages, page]);

  // ------------------- Summary -------------------
  const [totalRegistered, totalNotRegistered] = useMemo(() => {
    if (!selectedPayout?.rows) return [0, 0];
    const registered = selectedPayout.rows.filter((r) => r.STATUS === "Registered").length;
    return [registered, selectedPayout.rows.length - registered];
  }, [selectedPayout]);

  const getStatusColor = (status) => {
    switch (status) {
      case "Connected": return "success";
      case "Disconnected":
      case "Failed to reconnect": return "error";
      case "Reconnecting...":
      case "Connecting...": return "warning";
      default: return "default";
    }
  };

  // Export helper
const exportToExcel = (data, fileName) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
  XLSX.writeFile(wb, `${fileName}.xlsx`);
};

// Export Registered
const handleExportRegistered = () => {
  const data = selectedPayout.rows.filter(r => r.STATUS === "Registered");

  // Remove Encoder column
  const sanitized = data.map(r => {
    const { Encoder, ...rest } = r;
    return rest;
  });

  exportToExcel(sanitized, `${selectedPayout.fileName}-Registered`);
};

// Export Not Registered
const handleExportNotRegistered = () => {
  const data = selectedPayout.rows.filter(r => r.STATUS !== "Registered");

  const sanitized = data.map(r => {
    const { Encoder, ...rest } = r;
    return rest;
  });

  exportToExcel(sanitized, `${selectedPayout.fileName}-NotRegistered`);
};

// Export All visible columns except Encoder
const handleExportAll = () => {
  const colsToExport = visibleColumns.filter(c => c !== "Encoder");

  const data = selectedPayout.rows.map(row => {
    let newObj = {};
    colsToExport.forEach(c => {
      newObj[c] = row[c];
    });
    return newObj;
  });

  exportToExcel(data, `${selectedPayout.fileName}-AllData`);
};

  return (
    <Box display="flex" flexDirection={isMobile ? "column" : "row"}>
      {/* Mobile drawer toggle */}
      {isMobile && (
        <IconButton
          onClick={() => setDrawerOpen(true)}
          sx={{ position: "fixed", top: 10, left: 10, zIndex: 1200 }}
        >
          <MenuIcon />
        </IconButton>
      )}

      {/* Sidebar */}
      {isMobile ? (
        <Drawer
          anchor="left"
          open={drawerOpen}
          onClose={() => setDrawerOpen(false)}
          variant="temporary"
        >
          <EncodingSidebar onClose={() => setDrawerOpen(false)} />
        </Drawer>
      ) : (
        <EncodingSidebar collapsed={sidebarCollapsed} onToggle={setSidebarCollapsed} />
      )}

      {/* Main Content */}
      <Box
        sx={{
          flex: "1 1 auto",
          p: isMobile ? 2 : isTablet ? 2 : 3,
          width: mainContentWidth,
          transition: "width 0.3s",
          overflowX: "hidden",
        }}
      >
        {/* Header */}
        <Stack direction="row" justifyContent="space-between" alignItems="center" mb={3} flexWrap="wrap">
          <Typography variant={isMobile ? "h5" : "h4"}>Payout Monitoring</Typography>
          <Stack direction="row" alignItems="center" spacing={1}>
            {connectionStatus === "Connected" && (
              <Avatar sx={{ width: 12, height: 12, bgcolor: heartbeatOn ? "success.main" : "grey.300" }} />
            )}
            <Chip label={connectionStatus} color={getStatusColor(connectionStatus)} />
            <Typography variant="body2" color="text.secondary" sx={{ ml: 2 }}>
              Server Time: {serverTime.toLocaleString()}
            </Typography>
          </Stack>
        </Stack>

        {/* Select Payout */}
        <Box display="flex" flexDirection={isMobile || isTablet ? "column" : "row"} gap={2} mb={3}>
          <TextField
            select
            fullWidth
            size={isMobile ? "small" : "medium"}
            label="Choose payout schedule"
            value={selectedPayout ? selectedPayout.fileName : ""}
            onChange={(e) => fetchPayoutData(e.target.value)}
          >
            {importedFiles.map((file, i) => (
              <MenuItem key={i} value={file.name}>{file.name} — {file.date || "No Date"}</MenuItem>
            ))}
          </TextField>
        </Box>

        {/* Summary */}
        {selectedPayout && (
          <Stack direction={isMobile ? "column" : "row"} spacing={2} mb={3}>
            <Paper sx={{ p: 2, flex: 1, borderLeft: "5px solid green", position: "relative" }}>
              <IconButton
                size="small"
                sx={{ position: "absolute", top: 8, right: 8 }}
                onClick={handleExportRegistered}
              >
                <FileDownloadIcon sx={{ color: "green" }} />
              </IconButton>

              <Typography variant="subtitle2" color="text.secondary">Total Registered</Typography>
              <Typography variant="h6" sx={{ color: "green", fontWeight: 700 }}>{totalRegistered}</Typography>
            </Paper>
            <Paper sx={{ p: 2, flex: 1, borderLeft: "5px solid red", position: "relative" }}>
              <IconButton
                size="small"
                sx={{ position: "absolute", top: 8, right: 8 }}
                onClick={handleExportNotRegistered}
              >
                <FileDownloadIcon sx={{ color: "red" }} />
              </IconButton>

              <Typography variant="subtitle2" color="text.secondary">Total Not Registered</Typography>
              <Typography variant="h6" sx={{ color: "red", fontWeight: 700 }}>{totalNotRegistered}</Typography>
            </Paper>
          </Stack>
        )}

        {/* Column Visibility Dropdown */}
        <Box
            mb={2}
            sx={{
              display: "flex",
              justifyContent: "flex-end",
              alignItems: "center",
              gap: 1
            }}
          >
            {/* Export All Button */}
             <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 1.2,
              px: 1.5,
              py: 0.7,
              borderRadius: 2,
              bgcolor: "#e9f4ff",
              cursor: "pointer",
              transition: "0.2s",
              "&:hover": {
                bgcolor: "#d7ecff",
              },
            }}
            onClick={handleExportAll}
          >
            <FileDownloadIcon sx={{ color: "#1976d2" }} />
            <Typography
              variant="body2"
              sx={{
                color: "#1976d2",
                fontWeight: 600,
                letterSpacing: 0.2,
              }}
            >
              Export to Excel
            </Typography>
          </Box>

            <TextField
              select
              label="Columns"
              SelectProps={{
                multiple: true,
                value: visibleColumns,
                onChange: (e) => setVisibleColumns(e.target.value),
                renderValue: (selected) => {
                  if (!selected.length) return "Select columns";
                  if (selected.length === 1) return selected[0];
                  return `${selected.length} selected`;
                },
                MenuProps: { PaperProps: { sx: { maxHeight: 250 } } },
              }}
              size="small"
            >
              {columns.map((col) => (
                <MenuItem key={col} value={col}>
                  <Checkbox checked={visibleColumns.includes(col)} />
                  <Typography sx={{ ml: 1, fontSize: "0.85rem" }}>{col}</Typography>
                </MenuItem>
              ))}
            </TextField>
          </Box>

        {/* Table */}
        {selectedPayout ? (
          <Paper sx={{ p: isMobile ? 1 : 2 }}>
            <Typography variant="h5" align="center">{selectedPayout.title}</Typography>
            <Divider sx={{ mb: 2 }} />
            <Divider sx={{ mb: 2 }} />
          {/* Enhanced Search */}
          <Box mb={2}>
            <TextField
              fullWidth
              size="small"
              placeholder="Search any name, barangay, ID, etc..."
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1); }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon color="action" />
                  </InputAdornment>
                ),
                sx: {
                  borderRadius: 50,           // rounded pill shape
                  backgroundColor: "#f1f1f1", // light background
                  "& .MuiInputBase-input": {
                    padding: "10px 14px",     // more padding for comfort
                  },
                  "&:hover": {
                    backgroundColor: "#e0e0e0"
                  },
                  "&.Mui-focused": {
                    backgroundColor: "#ffffff",
                    boxShadow: `0 0 0 2px ${theme.palette.primary.main}33`, // subtle focus glow
                  }
                }
              }}
              variant="outlined"
            />
          </Box>
            <Divider sx={{ mb: 2 }} />
            <Typography variant="subtitle1" sx={{ mb: 1 }}>Excel Data Preview ({filteredRows.length} rows)</Typography>

            <TableContainer sx={{ overflowX: "auto" }}>
              <Table size={isMobile ? "small" : "medium"}>
                <TableHead>
                  <TableRow>
                    {columns
                      .filter((col) => visibleColumns.includes(col))
                      .map((col, idx) => (
                        <TableCell
                          key={idx}
                          sx={{
                            fontWeight: 700,
                            backgroundColor: "#f0f0f0",
                            whiteSpace: "nowrap",
                          }}
                        >
                          {col}
                        </TableCell>
                      ))}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paginatedRows.map((row, idx) => (
                    <TableRow
                      key={idx}
                      sx={{
                        backgroundColor:
                          row.STATUS === "Registered"
                            ? "#53e00dff" // light green for registered
                            : idx % 2 === 0
                            ? "#fafafa"
                            : "white",
                      }}
                    >
                      {columns
                        .filter((col) => visibleColumns.includes(col))
                        .map((col, i) => (
                          <TableCell key={i} sx={{ whiteSpace: "nowrap" }}>
                            {row[col] ?? ""}
                          </TableCell>
                        ))}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            {/* Pagination */}
            <Stack direction={isMobile ? "column" : "row"} spacing={2} justifyContent="center" alignItems="center" mt={2}>
              <Button variant="contained" disabled={page === 1} onClick={() => setPage(p => Math.max(1, p - 1))} fullWidth={isMobile}>Previous</Button>
              <Typography>Page {page} of {totalPages}</Typography>
              <Button variant="contained" disabled={page >= totalPages} onClick={() => setPage(p => Math.min(totalPages, p + 1))} fullWidth={isMobile}>Next</Button>
            </Stack>
          </Paper>
        ) : (
          <Typography>Select a payout to view data.</Typography>
        )}
      </Box>
    </Box>
  );
};

export default AdminPayoutMonitoring;