import React from "react";
import {
  Box,
  Typography,
  Card,
  Collapse,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Checkbox,
  Grid,
} from "@mui/material";
import { ExpandMore, ExpandLess } from "@mui/icons-material";

const ProfileAdvancedSettings = ({
  advancedOpen,
  setAdvancedOpen,
  selectedColumns,
  handleColumnToggle,
  allBarangays = [],
  selectedBarangays = [],
  handleBarangayChange,
  allPuroks = [],
  selectedPuroks = [],
  handlePurokChange,
}) => {
  const columnOptions = Object.keys(selectedColumns);
  const selectedColumnsList = columnOptions.filter(col => selectedColumns[col]);
  
  // Disable purok dropdown when all barangays or no barangays are selected
  const isPurokDisabled = selectedBarangays.length === 0 || selectedBarangays.length === allBarangays.length;

  return (
    <Card 
      sx={{ 
        bgcolor: "#fff", 
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)", 
        mb: 3,
        borderRadius: 1.5,
        border: "1px solid #e5e7eb"
      }}
    >
      <Box
        onClick={() => setAdvancedOpen(!advancedOpen)}
        sx={{
          p: 2.5,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          cursor: "pointer",
          "&:hover": { bgcolor: "#f8f9fa" },
          transition: "background-color 0.2s ease",
          borderBottom: advancedOpen ? "1px solid #e5e7eb" : "none"
        }}
      >
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, color: "#1a237e" }}>
            Advanced Settings
          </Typography>
          <Typography variant="caption" sx={{ color: "#666", display: "block", mt: 0.5 }}>
            Customize your view and filters
          </Typography>
        </Box>
        {advancedOpen ? (
          <ExpandLess sx={{ color: "#135bec", fontSize: 28 }} />
        ) : (
          <ExpandMore sx={{ color: "#135bec", fontSize: 28 }} />
        )}
      </Box>

      <Collapse in={advancedOpen}>
        <Box sx={{ p: 3, bgcolor: "#fafbfc" }}>
          <Grid container spacing={3}>
            {/* Select Barangay Dropdown */}
            <Grid item xs={12} md={6}>
              <FormControl fullWidth size="small">
                <InputLabel sx={{ fontWeight: 600 }}>Select Barangay</InputLabel>
                <Select
                  multiple
                  value={selectedBarangays}
                  onChange={(e) => handleBarangayChange(e.target.value)}
                  label="Select Barangay"
                  renderValue={(selected) =>
                    selected.length === 0
                      ? "All Barangays"
                      : selected.length === allBarangays.length
                      ? "All Barangays"
                      : `${selected.length} barangay${selected.length !== 1 ? 'ies' : ''} selected`
                  }
                  sx={{
                    borderRadius: 1,
                    "& .MuiOutlinedInput-root": {
                      backgroundColor: "#fff",
                    },
                  }}
                >
                  <MenuItem 
                    value="SELECT_ALL_BARANGAY" 
                    sx={{ 
                      fontWeight: 700, 
                      color: "#135bec",
                      backgroundColor: selectedBarangays.length === allBarangays.length ? "#e8ecff" : "transparent",
                      "&:hover": {
                        backgroundColor: "#f0f4ff",
                      }
                    }}
                  >
                    <Checkbox
                      checked={selectedBarangays.length === allBarangays.length}
                      indeterminate={selectedBarangays.length > 0 && selectedBarangays.length < allBarangays.length}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Typography sx={{ fontWeight: 700 }}>
                      {selectedBarangays.length === allBarangays.length ? "Deselect All" : "Select All"}
                    </Typography>
                  </MenuItem>
                  {allBarangays.length === 0 ? (
                    <MenuItem disabled sx={{ fontWeight: 600, color: "#999" }}>
                      No barangays available
                    </MenuItem>
                  ) : (
                    allBarangays.map((barangay) => (
                      <MenuItem key={barangay} value={barangay}>
                        <Checkbox
                          checked={selectedBarangays.includes(barangay)}
                          size="small"
                          sx={{ mr: 1 }}
                        />
                        <Typography sx={{ fontWeight: 500 }}>{barangay}</Typography>
                      </MenuItem>
                    ))
                  )}
                </Select>
              </FormControl>
            </Grid>

            {/* Select Purok Dropdown */}
            <Grid item xs={12} md={6}>
              <FormControl fullWidth size="small" disabled={isPurokDisabled}>
                <InputLabel sx={{ fontWeight: 600 }}>Select Purok</InputLabel>
                <Select
                  multiple
                  disabled={isPurokDisabled}
                  value={selectedPuroks}
                  onChange={(e) => handlePurokChange(e.target.value)}
                  label="Select Purok"
                  renderValue={(selected) =>
                    isPurokDisabled
                      ? "Select specific barangay first"
                      : selected.length === 0
                      ? "Select Purok"
                      : selected.length === allPuroks.length
                      ? "All Puroks"
                      : `${selected.length} purok${selected.length !== 1 ? 's' : ''} selected`
                  }
                  sx={{
                    borderRadius: 1,
                    "& .MuiOutlinedInput-root": {
                      backgroundColor: "#fff",
                    },
                  }}
                >
                  <MenuItem 
                    value="SELECT_ALL_PUROK" 
                    sx={{ 
                      fontWeight: 700, 
                      color: "#135bec",
                      backgroundColor: selectedPuroks.length === allPuroks.length ? "#e8ecff" : "transparent",
                      "&:hover": {
                        backgroundColor: "#f0f4ff",
                      }
                    }}
                  >
                    <Checkbox
                      checked={selectedPuroks.length === allPuroks.length}
                      indeterminate={selectedPuroks.length > 0 && selectedPuroks.length < allPuroks.length}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Typography sx={{ fontWeight: 700 }}>
                      {selectedPuroks.length === allPuroks.length ? "Deselect All" : "Select All"}
                    </Typography>
                  </MenuItem>
                  {allPuroks.length === 0 ? (
                    <MenuItem disabled sx={{ fontWeight: 600, color: "#999" }}>
                      No puroks available
                    </MenuItem>
                  ) : (
                    allPuroks.map((purok) => (
                      <MenuItem key={purok} value={purok}>
                        <Checkbox
                          checked={selectedPuroks.includes(purok)}
                          size="small"
                          sx={{ mr: 1 }}
                        />
                        <Typography sx={{ fontWeight: 500 }}>{purok}</Typography>
                      </MenuItem>
                    ))
                  )}
                </Select>
              </FormControl>
            </Grid>

            {/* Select Columns Dropdown */}
            <Grid item xs={12}>
              <FormControl fullWidth size="small">
                <InputLabel sx={{ fontWeight: 600 }}>Select Columns</InputLabel>
                <Select
                  multiple
                  value={Object.keys(selectedColumns).filter(col => selectedColumns[col])}
                  onChange={(e) => {
                    const value = e.target.value;
                    
                    if (value.includes("SELECT_ALL")) {
                      const allSelected = Object.keys(selectedColumns).every(col => selectedColumns[col]);
                      if (allSelected) {
                        columnOptions.forEach(col => {
                          if (selectedColumns[col]) {
                            handleColumnToggle(col);
                          }
                        });
                      } else {
                        columnOptions.forEach(col => {
                          if (!selectedColumns[col]) {
                            handleColumnToggle(col);
                          }
                        });
                      }
                    } else {
                      columnOptions.forEach(col => {
                        if (value.includes(col) && !selectedColumns[col]) {
                          handleColumnToggle(col);
                        } else if (!value.includes(col) && selectedColumns[col]) {
                          handleColumnToggle(col);
                        }
                      });
                    }
                  }}
                  label="Select Columns"
                  renderValue={(selected) =>
                    selected.length === columnOptions.length
                      ? "All Columns"
                      : selected.length === 0
                      ? "No Columns Selected"
                      : `${selected.length} column${selected.length !== 1 ? 's' : ''} selected`
                  }
                  sx={{
                    borderRadius: 1,
                    "& .MuiOutlinedInput-root": {
                      backgroundColor: "#fff",
                    },
                  }}
                >
                  <MenuItem 
                    value="SELECT_ALL" 
                    sx={{ 
                      fontWeight: 700, 
                      color: "#135bec",
                      backgroundColor: selectedColumnsList.length === columnOptions.length ? "#e8ecff" : "transparent",
                      "&:hover": {
                        backgroundColor: "#f0f4ff",
                      }
                    }}
                  >
                    <Checkbox
                      checked={selectedColumnsList.length === columnOptions.length}
                      indeterminate={selectedColumnsList.length > 0 && selectedColumnsList.length < columnOptions.length}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Typography sx={{ fontWeight: 700 }}>
                      {selectedColumnsList.length === columnOptions.length ? "Deselect All" : "Select All"}
                    </Typography>
                  </MenuItem>
                  {columnOptions.map((column) => (
                    <MenuItem key={column} value={column}>
                      <Checkbox
                        checked={selectedColumns[column]}
                        size="small"
                        sx={{ mr: 1 }}
                      />
                      <Typography sx={{ fontWeight: 500 }}>{column}</Typography>
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>

          {/* Summary Section */}
          <Box sx={{ mt: 3, pt: 3, borderTop: "1px solid #e5e7eb" }}>
            <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>
              Active Columns: <span style={{ color: "#135bec", fontWeight: 700 }}>{selectedColumnsList.join(", ") || "None"}</span>
            </Typography>
          </Box>
        </Box>
      </Collapse>
    </Card>
  );
};

export default ProfileAdvancedSettings;
