// src/pages/admin/AdminEncoding.jsx
import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Toolbar } from "@mui/material";
import EncodingSidebar from "../../components/EncodingSidebar";

const AdminEncoding = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const role = localStorage.getItem("role");
    if (!role || role !== "admin") {
      // Redirect to login if not logged in offline
      navigate("/login");
    }
  }, [navigate]);

  const name = localStorage.getItem("name") || "Admin";

  return (
    <Box sx={{ display: "flex" }}>
      <EncodingSidebar />
      <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
        <Toolbar />
        <Typography variant="h4" sx={{ mb: 2 }}>
          Welcome, {name}!
        </Typography>
        <Typography>
          This is the Encoding Section Admin Dashboard. From here you can manage encoding tasks and users offline.
        </Typography>
      </Box>
    </Box>
  );
};

export default AdminEncoding;