// src/pages/admin/AdminImportTask.jsx
import React, { useState, useEffect } from "react";
import {
  Box,
  Button,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  LinearProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@mui/material";
import UploadFileIcon from "@mui/icons-material/UploadFile";
import DeleteIcon from "@mui/icons-material/Delete";
import EncodingSidebar from "../../components/EncodingSidebar";
import * as XLSX from "xlsx";
import io from "socket.io-client";
import dataDB from "../../db/dataDB";  // <-- LOCAL DB

const SERVER_URL = "http://192.168.0.149:4000"; // LAN server IP


const AdminImportTask = () => {
  const [file, setFile] = useState(null);
  const [tasks, setTasks] = useState([]);
  const [progress, setProgress] = useState(0);
  const [showDialog, setShowDialog] = useState(false);
  const [importing, setImporting] = useState(false);
  const [deleteDialog, setDeleteDialog] = useState({ open: false, index: null });

  // Load from IndexedDB first
  useEffect(() => {
    async function loadLocal() {
      const localTasks = await dataDB.tasks.toArray();
      setTasks(localTasks);
    }
    loadLocal();
  }, []);

  // Sync with server
  useEffect(() => {
    const socket = io(SERVER_URL);

    // Fetch from server & merge to local DB
    fetch(`${SERVER_URL}/getData`)
      .then((res) => res.json())
      .then(async (serverTasks) => {
        if (!serverTasks) return;

        // Remove existing IDs so Dexie auto-generates new ones
        const sanitized = serverTasks.map(({ id, ...rest }) => rest);

        await dataDB.tasks.clear();
        await dataDB.tasks.bulkPut(sanitized);
        setTasks(sanitized);
      })
      .catch(() => console.log("⚠️ Server not reachable"));

    socket.on("dataUpdated", async (serverTasks) => {
      const sanitized = serverTasks.map(({ id, ...rest }) => rest);
      await dataDB.tasks.clear();
      await dataDB.tasks.bulkPut(sanitized);
      setTasks(sanitized);
    });

    return () => socket.disconnect();
  }, []);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    setProgress(0);
  };

  const handleImportClick = () => {
    if (!file) return alert("Please select a file first.");
    setShowDialog(true);
  };

  const handleConfirmImport = () => {
    setShowDialog(false);
    setImporting(true);

    const reader = new FileReader();
    reader.onload = (e) => {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: "array" });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

      let percent = 0;
      const interval = setInterval(async () => {
        if (percent < 100) {
          percent += 5;
          setProgress(percent);
        } else {
          clearInterval(interval);

          const newTask = {
            name: file.name,
            importedAt: new Date().toLocaleString(),
            data: rows,
          };

          const updatedTasks = [newTask, ...tasks];
          setTasks(updatedTasks);

          // Save to IndexedDB (auto-id, safe)
          await dataDB.tasks.add(newTask);

          // Save to server
          try {
            await fetch(`${SERVER_URL}/updateData`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(updatedTasks),
            });
          } catch (err) {
            console.error("❌ Sync failed:", err);
          }

          setImporting(false);
          setFile(null);
          setProgress(0);
        }
      }, 50);
    };

    reader.readAsArrayBuffer(file);
  };

  const handleDelete = (index) => {
    setDeleteDialog({ open: true, index });
  };

  const confirmDelete = async () => {
    const updatedTasks = [...tasks];
    const removed = updatedTasks.splice(deleteDialog.index, 1);
    setTasks(updatedTasks);

    // Delete from IndexedDB
    await dataDB.tasks.where("name").equals(removed[0].name).delete();

    // Sync to server
    try {
      await fetch(`${SERVER_URL}/updateData`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedTasks),
      });
    } catch (err) {
      console.error("❌ Failed to sync deletion", err);
    }

    setDeleteDialog({ open: false, index: null });
  };

  return (
    <Box display="flex">
      <EncodingSidebar />
      <Box flex={1} p={3}>
        <Typography variant="h4" gutterBottom>
          Import Tasks (IndexedDB + LAN Sync)
        </Typography>

        <Box display="flex" alignItems="center" gap={2} mb={3}>
          <Button variant="contained" component="label" startIcon={<UploadFileIcon />} disabled={importing}>
            Choose File
            <input type="file" hidden accept=".xlsx,.xls" onChange={handleFileChange} />
          </Button>

          {file && <Typography>{file.name}</Typography>}

          <Button variant="contained" color="success" onClick={handleImportClick} disabled={!file || importing}>
            Import Tasks
          </Button>
        </Box>

        {importing && (
          <Box mb={3}>
            <Typography>Importing... {progress}%</Typography>
            <LinearProgress variant="determinate" value={progress} />
          </Box>
        )}

        {tasks.length > 0 && (
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Imported File Name</TableCell>
                  <TableCell>Imported At</TableCell>
                  <TableCell>Action</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {tasks.map((t, index) => (
                  <TableRow key={index}>
                    <TableCell>{t.name}</TableCell>
                    <TableCell>{t.importedAt}</TableCell>
                    <TableCell>
                      <Button variant="outlined" color="error" startIcon={<DeleteIcon />} onClick={() => handleDelete(index)}>
                        Delete
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}

        {/* Confirm Import */}
        <Dialog open={showDialog} onClose={() => setShowDialog(false)}>
          <DialogTitle>Confirm Import</DialogTitle>
          <DialogContent>
            Importing this file updates both local IndexedDB and all connected devices.
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowDialog(false)}>Cancel</Button>
            <Button onClick={handleConfirmImport} variant="contained">Yes, Import</Button>
          </DialogActions>
        </Dialog>

        {/* Confirm Delete */}
        <Dialog open={deleteDialog.open} onClose={() => setDeleteDialog({ open: false, index: null })}>
          <DialogTitle>Delete Task</DialogTitle>
          <DialogContent>This will delete from local storage and sync to all devices.</DialogContent>
          <DialogActions>
            <Button onClick={() => setDeleteDialog({ open: false, index: null })}>Cancel</Button>
            <Button onClick={confirmDelete} variant="contained" color="error">Delete</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
};

export default AdminImportTask;