// src/pages/encoder/PayoutTask.jsx
import React, { useState, useEffect, useMemo, useRef } from "react";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableHead,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Divider,
  TextField,
  MenuItem,
  Stack,
  Button,
  Chip,
  Checkbox,
  useMediaQuery,
  useTheme,
  Drawer,
  IconButton,
  Avatar,
  InputAdornment,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import MenuIcon from "@mui/icons-material/Menu";
import EncodingSidebar from "../../components/EncodingSidebar";
import PayoutTaskDialog from "./dialogs/PayoutTaskDialog";
import io from "socket.io-client";

const SERVER_URL = "http://192.168.0.149:4000";

const PayoutTask = () => {
  const [importedFiles, setImportedFiles] = useState([]);
  const [selectedPayout, setSelectedPayout] = useState(null);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState("Connecting...");
  const [heartbeatOn, setHeartbeatOn] = useState(false);
  const [serverTime, setServerTime] = useState(new Date());
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedRow, setSelectedRow] = useState(null);
  const [encoderUsername, setEncoderUsername] = useState("");
  const [visibleColumns, setVisibleColumns] = useState([]);
  const [rowsPerPage, setRowsPerPage] = useState(25);

  const socketRef = useRef(null);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery(theme.breakpoints.between("sm", "md"));
  const drawerWidth = 265;
  const collapsedWidth = 60;
  const mainContentWidth = isMobile
    ? "100%"
    : `calc(100% - ${sidebarCollapsed ? collapsedWidth : drawerWidth}px)`;

  // ------------------- Live Server Time -------------------
  useEffect(() => {
    const interval = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  // ------------------- Fetch logged-in encoder -------------------
  useEffect(() => {
    const username = localStorage.getItem("username");
    if (username) setEncoderUsername(username);
  }, []);

  // ------------------- Fetch imported files and first payout -------------------
  useEffect(() => {
    const fetchImportedFiles = async () => {
      try {
        const res = await fetch(`${SERVER_URL}/getImportedFiles`);
        const files = await res.json();
        setImportedFiles(files || []);
        if (files.length > 0) fetchPayoutData(files[0].name);
      } catch (err) {
        console.error("Failed to fetch imported files:", err);
      }
    };
    fetchImportedFiles();
  }, []);

  // ------------------- Fetch payout data -------------------
  const fetchPayoutData = async (fileName, clearView = true) => {
    try {
      const res = await fetch(`${SERVER_URL}/getPayouts`);
      const payouts = await res.json();
      const data = payouts.find((p) => p.fileName === fileName);
      if (data) {
        data.rows = data.rows.map((row, idx) => ({ _rowIndex: idx, Encoder: row.Encoder || "", Timestamp: row.Timestamp || "", ...row }));
        setSelectedPayout(data);
        if (clearView) {
          setSearch("");
          setPage(1);
        }
      }
    } catch (err) {
      console.error("Failed to fetch payout data:", err);
    }
  };

  // ------------------- Socket Connection -------------------
  useEffect(() => {
    socketRef.current = io(SERVER_URL, { reconnectionAttempts: 5, transports: ["websocket"] });
    socketRef.current.on("connect", () => setConnectionStatus("Connected"));
    socketRef.current.on("disconnect", () => setConnectionStatus("Disconnected"));
    socketRef.current.on("reconnect_attempt", () => setConnectionStatus("Reconnecting..."));
    socketRef.current.on("reconnect_failed", () => setConnectionStatus("Failed to reconnect"));

    socketRef.current.on("payoutsUpdated", (updatedFiles) => {
      if (selectedPayout?.fileName && updatedFiles.includes(selectedPayout.fileName)) {
        // update rows without clearing user's current search/page
        fetchPayoutData(selectedPayout.fileName, false);
      }
      setImportedFiles(updatedFiles || []);
    });

    return () => socketRef.current.disconnect();
  }, [selectedPayout]);

  // ------------------- Heartbeat Indicator -------------------
  useEffect(() => {
    if (connectionStatus === "Connected") {
      const interval = setInterval(() => setHeartbeatOn((prev) => !prev), 500);
      return () => clearInterval(interval);
    }
    setHeartbeatOn(false);
  }, [connectionStatus]);

  // ------------------- Columns -------------------
  const columns = useMemo(() => {
    if (!selectedPayout?.rows?.length) return [];
    const allCols = Object.keys(selectedPayout.rows[0]).filter((c) => c !== "Encoder" && c !== "Timestamp");
    const statusIdx = allCols.indexOf("STATUS");
    if (statusIdx >= 0) {
      allCols.splice(statusIdx + 1, 0, "Encoder", "Timestamp");
    }
    return allCols;
  }, [selectedPayout]);

  // Load and save visibleColumns to localStorage
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("visibleColumns") || "[]");
    const valid = columns.filter((col) => saved.includes(col));
    setVisibleColumns(valid.length ? valid : columns);
  }, [columns]);
  useEffect(() => localStorage.setItem("visibleColumns", JSON.stringify(visibleColumns)), [visibleColumns]);

  // ------------------- Filtered & Paginated Rows -------------------
  const filteredRows = useMemo(() => {
    if (!selectedPayout?.rows) return [];
    if (!search.trim()) return selectedPayout.rows;
    const lower = search.toLowerCase();
    return selectedPayout.rows.filter((row) => Object.values(row).some((val) => String(val).toLowerCase().includes(lower)));
  }, [selectedPayout, search]);

  const totalPages = Math.max(1, Math.ceil(filteredRows.length / rowsPerPage));
  const paginatedRows = useMemo(() => {
    const start = (page - 1) * rowsPerPage;
    return filteredRows.slice(start, start + rowsPerPage);
  }, [filteredRows, page, rowsPerPage]);
  useEffect(() => { if (page > totalPages) setPage(1); }, [totalPages, page]);

  // ------------------- Status Summary -------------------
  const [totalRegistered, totalNotRegistered] = useMemo(() => {
    if (!selectedPayout?.rows) return [0, 0];
    const reg = selectedPayout.rows.filter((r) => r.STATUS === "Registered").length;
    return [reg, selectedPayout.rows.length - reg];
  }, [selectedPayout]);

  const getStatusColor = (status) => {
    switch (status) {
      case "Connected": return "success";
      case "Disconnected":
      case "Failed to reconnect": return "error";
      case "Reconnecting...":
      case "Connecting...": return "warning";
      default: return "default";
    }
  };

  const openRowDialog = (row) => { setSelectedRow(row); setDialogOpen(true); };

  // ------------------- Handle Reset -------------------
  const handleReset = async (row) => {
    try {
      await fetch(`${SERVER_URL}/resetRow`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fileName: selectedPayout.fileName, rowIndex: row._rowIndex }) });
      setSelectedPayout((prev) => {
        const newRows = [...prev.rows];
        newRows[row._rowIndex] = { ...newRows[row._rowIndex], STATUS: "", Encoder: "", Timestamp: "" };
        return { ...prev, rows: newRows };
      });
      setDialogOpen(false);
    } catch (err) { console.error(err); alert("Failed to reset row."); }
  };

  // ------------------- Handle Register -------------------
  const handleRegister = async (row) => {
    try {
      const timestamp = new Date().toLocaleString();
      await fetch(`${SERVER_URL}/registerRow`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fileName: selectedPayout.fileName, rowIndex: row._rowIndex, encoder: encoderUsername, timestamp }) });
      setSelectedPayout((prev) => {
        const newRows = [...prev.rows];
        newRows[row._rowIndex] = { ...newRows[row._rowIndex], STATUS: "Registered", Encoder: encoderUsername, Timestamp: timestamp };
        return { ...prev, rows: newRows };
      });
      setDialogOpen(false);
    } catch (err) { console.error(err); alert("Failed to register row."); }
  };

  // ------------------- Render -------------------
  return (
    <Box display="flex" flexDirection={isMobile ? "column" : "row"}>
      {isMobile && <IconButton onClick={() => setDrawerOpen(true)} sx={{ position: "fixed", top: 10, left: 10, zIndex: 1200 }}><MenuIcon /></IconButton>}

      {isMobile ? (
        <Drawer anchor="left" open={drawerOpen} onClose={() => setDrawerOpen(false)}>
          <EncodingSidebar onClose={() => setDrawerOpen(false)} />
        </Drawer>
      ) : (
        <EncodingSidebar collapsed={sidebarCollapsed} onToggle={setSidebarCollapsed} />
      )}

      <Box sx={{ flex: 1, p: isMobile ? 2 : isTablet ? 2 : 3, width: mainContentWidth, transition: "width 0.3s", overflowX: "hidden" }}>
        {/* Header */}
        <Stack direction="row" justifyContent="space-between" alignItems="center" mb={3}>
          <Typography variant="h4">Payout Task</Typography>
          <Stack direction="row" spacing={1} alignItems="center">
            {connectionStatus === "Connected" && <Avatar sx={{ width: 12, height: 12, bgcolor: heartbeatOn ? "success.main" : "grey.300" }} />}
            <Chip label={connectionStatus} color={getStatusColor(connectionStatus)} />
            <Typography variant="body2" color="text.secondary" sx={{ ml: 2 }}>Server Time: {serverTime.toLocaleString()}</Typography>
          </Stack>
        </Stack>

        {/* Payout Select */}
        <Box display="flex" flexDirection={isMobile ? "column" : "row"} gap={2} mb={3}>
          <TextField select fullWidth size="medium" label="Choose payout schedule" value={selectedPayout?.fileName || ""} onChange={(e) => fetchPayoutData(e.target.value)}>
            {importedFiles.map((file, i) => <MenuItem key={i} value={file.name}>{file.name} — {file.date || "No Date"}</MenuItem>)}
          </TextField>
        </Box>

        {/* Summary */}
        {selectedPayout && (
          <Stack direction={isMobile ? "column" : "row"} spacing={2} mb={3}>
            <Paper sx={{ p: 2, flex: 1, borderLeft: "5px solid green" }}>
              <Typography variant="subtitle2">Total Registered</Typography>
              <Typography variant="h6" sx={{ color: "green", fontWeight: 700 }}>{totalRegistered}</Typography>
            </Paper>
            <Paper sx={{ p: 2, flex: 1, borderLeft: "5px solid red" }}>
              <Typography variant="subtitle2">Total Not Registered</Typography>
              <Typography variant="h6" sx={{ color: "red", fontWeight: 700 }}>{totalNotRegistered}</Typography>
            </Paper>
          </Stack>
        )}

        {/* Controls */}
        <Box mb={2} sx={{ display: "flex", justifyContent: "flex-end", gap: 2, flexWrap: "wrap" }}>
          <TextField select size="small" label="Rows" value={rowsPerPage} onChange={(e) => { setRowsPerPage(Number(e.target.value)); setPage(1); }} sx={{ width: 100 }}>
            {[10, 25, 50, 100].map((limit) => <MenuItem key={limit} value={limit}>{limit}</MenuItem>)}
          </TextField>

          <TextField select label="Columns" SelectProps={{ multiple: true, value: visibleColumns, onChange: (e) => setVisibleColumns(e.target.value), renderValue: (selected) => !selected.length ? "Select columns" : selected.length === 1 ? selected[0] : `${selected.length} selected`, MenuProps: { PaperProps: { sx: { maxHeight: 250 } } } }} size="small">
            {columns.map((col) => (
              <MenuItem key={col} value={col}>
                <Checkbox checked={visibleColumns.includes(col)} />
                <Typography sx={{ ml: 1, fontSize: "0.85rem" }}>{col}</Typography>
              </MenuItem>
            ))}
          </TextField>
        </Box>

        {/* Table */}
        {selectedPayout ? (
          <Paper sx={{ p: isMobile ? 1 : 2 }}>
            <Typography variant="h5" align="center">{selectedPayout.title}</Typography>
            <Divider sx={{ mb: 2 }} />

            <Box mb={2}>
              <TextField
                fullWidth
                size="small"
                placeholder="Search..."
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                InputProps={{ startAdornment: <InputAdornment position="start"><SearchIcon color="action" /></InputAdornment>, sx: { borderRadius: 50, backgroundColor: "#f1f1f1", "& .MuiInputBase-input": { padding: "10px 14px" } } }}
                variant="outlined"
              />
            </Box>

            <TableContainer sx={{ overflowX: "auto" }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    {columns.filter((col) => visibleColumns.includes(col)).map((col, idx) => <TableCell key={idx} sx={{ fontWeight: 700, backgroundColor: "#f0f0f0", whiteSpace: "nowrap" }}>{col}</TableCell>)}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paginatedRows.map((row, idx) => (
                    <TableRow key={idx} hover onClick={() => openRowDialog(row)} sx={{ cursor: "pointer", backgroundColor: row.STATUS === "Registered" ? "#06f32eff" : idx % 2 === 0 ? "#fafafa" : "white" }}>
                      {columns.filter((col) => visibleColumns.includes(col)).map((col, i) => <TableCell key={i} sx={{ whiteSpace: "nowrap", padding: { xs: "6px 8px", sm: "8px 12px" }, fontSize: { xs: "0.8rem", sm: "0.9rem" } }}>{row[col] ?? ""}</TableCell>)}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            {/* Pagination */}
            <Stack direction="row" spacing={2} justifyContent="center" alignItems="center" mt={2} flexWrap="wrap">
              <Button variant="contained" disabled={page === 1} onClick={() => setPage(page - 1)} fullWidth={isMobile}>Previous</Button>
              <Typography>Page {page} of {totalPages}</Typography>
              <Button variant="contained" disabled={page >= totalPages} onClick={() => setPage(page + 1)} fullWidth={isMobile}>Next</Button>
            </Stack>

            {/* Row Dialog */}
            <PayoutTaskDialog open={dialogOpen} onClose={() => setDialogOpen(false)} rowData={selectedRow} onRegister={handleRegister} onReset={handleReset} encoder={encoderUsername} />
          </Paper>
        ) : (
          <Typography>Select a payout to view data.</Typography>
        )}
      </Box>
    </Box>
  );
};

export default PayoutTask;