import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  CircularProgress,
} from "@mui/material";
import { FileDownload, Print, FamilyRestroom, People, Cake, PendingActions } from "@mui/icons-material";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from "recharts";
import { db } from "../../firebase";
import { collection, query, where, getCountFromServer, getDocs, orderBy, limit, startAfter } from "firebase/firestore";

const ReportsOverview = () => {
  const [tabValue, setTabValue] = useState(0);
  const [barangayData, setBarangayData] = useState([]);
  const [votersBarangayData, setVotersBarangayData] = useState([]);
  const [profiledBarangayData, setProfiledBarangayData] = useState([]);

  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({
    totalFamilies: 0,
    totalVoters: 0,
    largestAgeGroup: "18-24",
    pendingUpdates: 0,
  });

  // Calculate age from birthdate
  const calculateAge = (birthDate) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = birthDate.toDate ? birthDate.toDate() : new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  // Get age bracket from age
  const getAgeBracket = (age) => {
    if (!age) return null;
    if (age >= 10 && age <= 17) return "10-17";
    if (age >= 18 && age <= 24) return "18-24";
    if (age >= 25 && age <= 34) return "25-34";
    if (age >= 35 && age <= 44) return "35-44";
    if (age >= 45 && age <= 54) return "45-54";
    if (age >= 55 && age <= 64) return "55-64";
    if (age >= 65) return "65+";
    return null;
  };

  // Fetch and process data
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        // Check if data exists in cache
        const cachedData = localStorage.getItem("reportsOverviewData");
        if (cachedData) {
          const { votersData, profiledData, totalVoters, pendingUpdates } = JSON.parse(cachedData);
          setVotersBarangayData(votersData);
          setProfiledBarangayData(profiledData);
          setBarangayData(votersData);
          setStats({
            totalFamilies: Math.floor(totalVoters / 4),
            totalVoters: totalVoters,
            largestAgeGroup: "18-24",
            pendingUpdates: pendingUpdates,
          });
          setLoading(false);
          return;
        }

        const votersCol = collection(db, "voters");
        
        // Get total voters count
        const totalCount = await getCountFromServer(query(votersCol));
        
        // Get pending updates (no PoliticalStatus)
        const pendingCount = await getCountFromServer(
          query(votersCol, where("PoliticalStatus", "==", ""))
        );

        // Fetch all voters data
        const votersMap = new Map();
        const profiledMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 5000;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = voter.ProfiledBarangay || "[NO BARANGAY]";
            const birthDate = voter.BirthDate;
            const age = calculateAge(birthDate);
            const ageBracket = getAgeBracket(age);
            const votingStatus = voter.VotingStatus || "UNKNOWN";
            const politicalStatus = voter.PoliticalStatus || "";

            if (!ageBracket) return;

            // For Voters Barangay tab - only VOTER status
            if (votingStatus === "VOTER") {
              if (!votersMap.has(barangay)) {
                votersMap.set(barangay, {
                  barangay: barangay,
                  "10-17": 0,
                  "18-24": 0,
                  "25-34": 0,
                  "35-44": 0,
                  "45-54": 0,
                  "55-64": 0,
                  "65+": 0,
                  total: 0,
                });
              }
              const record = votersMap.get(barangay);
              record[ageBracket]++;
              record.total++;
            }

            // For Profiled Barangay tab
            // EXCLUDE: NON-VOTER + UNTAGGED combination
            const isNonVoterUntagged = votingStatus === "NON-VOTER" && politicalStatus === "UNTAGGED";
            if (!isNonVoterUntagged) {
              if (!profiledMap.has(barangay)) {
                profiledMap.set(barangay, {
                  barangay: barangay,
                  "10-17": 0,
                  "18-24": 0,
                  "25-34": 0,
                  "35-44": 0,
                  "45-54": 0,
                  "55-64": 0,
                  "65+": 0,
                  total: 0,
                });
              }
              const profiledRecord = profiledMap.get(barangay);
              profiledRecord[ageBracket]++;
              profiledRecord.total++;
            }
          });

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        // Sort and set data - put [NO BARANGAY] at the end
        const votersArray = Array.from(votersMap.values()).sort((a, b) => {
          if (a.barangay === "[NO BARANGAY]") return 1;
          if (b.barangay === "[NO BARANGAY]") return -1;
          return a.barangay.localeCompare(b.barangay);
        });
        const profiledArray = Array.from(profiledMap.values()).sort((a, b) => {
          if (a.barangay === "[NO BARANGAY]") return 1;
          if (b.barangay === "[NO BARANGAY]") return -1;
          return a.barangay.localeCompare(b.barangay);
        });

        setVotersBarangayData(votersArray);
        setProfiledBarangayData(profiledArray);
        setBarangayData(votersArray);

        const statsData = {
          totalFamilies: Math.floor(totalCount.data().count / 4),
          totalVoters: totalCount.data().count,
          largestAgeGroup: "18-24",
          pendingUpdates: pendingCount.data().count,
        };
        setStats(statsData);

        // Cache the data
        localStorage.setItem("reportsOverviewData", JSON.stringify({
          votersData: votersArray,
          profiledData: profiledArray,
          totalVoters: statsData.totalVoters,
          pendingUpdates: statsData.pendingUpdates,
        }));
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Update table data when tab changes
  const handleTabChange = (e, newValue) => {
    setTabValue(newValue);
    setBarangayData(newValue === 0 ? votersBarangayData : profiledBarangayData);
  };

  // Chart data for age distribution
  const ageDistributionData = [
    { name: "10-17", value: 450 },
    { name: "18-24", value: 820 },
    { name: "25-34", value: 720 },
    { name: "35-44", value: 580 },
    { name: "45-54", value: 520 },
    { name: "55-64", value: 380 },
    { name: "65+", value: 180 },
  ];

  const colors = ["#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6", "#ec4899", "#f97316"];

  const ageBrackets = [
    { bracket: "10-24", label: "10-24", count: 1270 },
    { bracket: "25-34", label: "25-34", count: 720 },
    { bracket: "35-44", label: "35-44", count: 580 },
    { bracket: "45-54", label: "45-54", count: 520 },
    { bracket: "55-64", label: "55-64", count: 380 },
    { bracket: "65+", label: "65+", count: 180 },
  ];

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box sx={{ flexGrow: 1, width: { xs: "100%", md: "calc(100% - 260px)" }, display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 2, overflowX: "auto" }}>

          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Demographic Reports
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button startIcon={<FileDownload />} variant="outlined" size="small" sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}>
                Export PDF
              </Button>
              <Button startIcon={<Print />} variant="contained" color="success" size="small" sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}>
                Print Email
              </Button>
            </Box>
          </Box>

          {/* Stats Cards */}
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={12} sm={6} md={3}>
              <Card sx={{ bgcolor: "#f0f4ff", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#4f46e5", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <FamilyRestroom sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Most Profiled Families
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.totalFamilies.toLocaleString()}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card sx={{ bgcolor: "#f0f9ff", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#10b981", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <People sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Total Voters
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.totalVoters.toLocaleString()}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card sx={{ bgcolor: "#fef2f2", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#ef4444", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <Cake sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Largest Age Group
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.largestAgeGroup}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card sx={{ bgcolor: "#fff7ed", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#f97316", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <PendingActions sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Pending Updates
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.pendingUpdates.toLocaleString()}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Tabs and Table */}
          <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", mb: 3 }}>
            <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
              <Tabs value={tabValue} onChange={handleTabChange} sx={{ minHeight: 40 }}>
                <Tab label="Voters Barangay" sx={{ fontSize: 13, textTransform: "none", fontWeight: 600 }} />
                <Tab label="Profiled Barangay" sx={{ fontSize: 13, textTransform: "none", fontWeight: 600 }} />
              </Tabs>
            </Box>

            {loading ? (
              <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", py: 4 }}>
                <CircularProgress />
              </Box>
            ) : (
              <TableContainer>
                <Table size="small">
                <TableHead>
                  <TableRow sx={{ bgcolor: "#1a237e" }}>
                    <TableCell sx={{ color: "#fff", fontWeight: 700, fontSize: 12 }}>ID</TableCell>
                    <TableCell sx={{ color: "#fff", fontWeight: 700, fontSize: 12 }}>BARANGAY</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#3b82f6", p: 1 }}>10-17</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#10b981", p: 1 }}>18-24</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#f59e0b", p: 1 }}>25-34</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#ef4444", p: 1 }}>35-44</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#8b5cf6", p: 1 }}>45-54</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#ec4899", p: 1 }}>55-64</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: "#f97316", p: 1 }}>65+</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, p: 1 }}>TOTAL</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {barangayData.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={10} align="center" sx={{ py: 4 }}>
                        <Typography variant="body2" sx={{ color: "#999" }}>
                          No data available
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    <>
                      {barangayData.map((row, idx) => (
                        <TableRow 
                          key={idx} 
                          hover 
                          sx={{ 
                            "&:hover": { bgcolor: "#f5f7fa" },
                            bgcolor: row.barangay === "[NO BARANGAY]" ? "#fff3e0" : "inherit",
                            borderTop: row.barangay === "[NO BARANGAY]" ? "2px solid #ff9800" : "inherit"
                          }}
                        >
                          <TableCell sx={{ fontWeight: 600, color: "#666", fontSize: 12, p: 1 }}>{idx + 1}</TableCell>
                          <TableCell sx={{ 
                            fontWeight: row.barangay === "[NO BARANGAY]" ? 700 : 600, 
                            color: row.barangay === "[NO BARANGAY]" ? "#e65100" : "#1a237e", 
                            fontSize: 12, 
                            p: 1 
                          }}>
                            {row.barangay}
                          </TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["10-17"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["18-24"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["25-34"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["35-44"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["45-54"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["55-64"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1 }}>{row["65+"]}</TableCell>
                          <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>{row.total}</TableCell>
                        </TableRow>
                      ))}
                      <TableRow sx={{ bgcolor: "#f5f7fa", fontWeight: 700 }}>
                        <TableCell colSpan={2} sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>OVERALL TOTAL</TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["10-17"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["18-24"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["25-34"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["35-44"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["45-54"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["55-64"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row["65+"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.reduce((sum, row) => sum + (row.total || 0), 0)}
                        </TableCell>
                      </TableRow>
                    </>
                  )}
                </TableBody>
              </Table>
              </TableContainer>
            )}
          </Card>

          {/* Charts Section */}
          <Grid container spacing={2} sx={{ width: "100%", maxWidth: "100%" }}>
            {/* Standard Age Brackets */}
            <Grid item xs={12} sx={{ width: "100%" }}>
              <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", height: "100%" }}>
                <CardContent sx={{ p: 2 }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#1a237e", mb: 1.5, fontSize: 13 }}>
                    Standard Age Brackets
                  </Typography>
                  <Box sx={{ display: "flex", flexDirection: "column", gap: 0.75 }}>
                    {ageBrackets.map((item, idx) => (
                      <Box key={idx} sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Box sx={{ width: 12, height: 12, bgcolor: colors[idx], borderRadius: 1.5, flexShrink: 0 }} />
                        <Box sx={{ flex: 1 }}>
                          <Typography sx={{ fontWeight: 600, color: "#666", fontSize: 12 }}>
                            {item.label}
                          </Typography>
                          <Typography sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12 }}>
                            {item.count.toLocaleString()}
                          </Typography>
                        </Box>
                      </Box>
                    ))}
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            {/* Distribution Overview Chart */}
            <Grid item xs={12} sx={{ width: "100%" }}>
              <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", width: "100%", height: "100%" }}>
                <CardContent sx={{ p: 1.5, width: "100%" }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#1a237e", mb: 1.5, fontSize: 13 }}>
                    Distribution Overview
                  </Typography>
                  <ResponsiveContainer width="100%" height={400}>
                    <BarChart data={ageDistributionData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                      <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                      <YAxis tick={{ fontSize: 12 }} />
                      <Tooltip contentStyle={{ fontSize: 12 }} />
                      <Bar dataKey="value" fill="#3b82f6" radius={[6, 6, 0, 0]}>
                        {ageDistributionData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={colors[index]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

        </Box>
      </Box>
    </Box>
  );
};

export default ReportsOverview;
