// src/App.js
import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { auth, db } from "./firebase";
import { doc, getDoc } from "firebase/firestore";

// Page imports
import Login from "./pages/Login";
import Dashboard from "./pages/admin/Dashboard"; // <-- New Dashboard

// Admin Pages
import AdminDashboard from "./pages/admin/AdminDashboard";
import AdminPcvlMgt from "./pages/admin/AdminPcvlMgt";
import AdminVotersProfileMgt from "./pages/admin/AdminVotersProfileMgt";
import AdminFamilyTree from "./pages/admin/AdminFamilyTree";
import AdminEncoding from "./pages/admin/AdminEncoding";
import AdminImportTask from "./pages/admin/AdminImportTask";
import AdminTask from "./pages/admin/AdminTask";
import PayoutManagement from "./pages/admin/AdminPayoutManagement"; // Offline Payout Management
import PayoutMonitoring from "./pages/admin/AdminPayoutMonitoring"; // Offline Payout Monitoring

// Encoder Pages
import EncoderEncoding from "./pages/encoder/EncoderEncoding";
import UserManagement from "./pages/admin/UserManagement";
import PayoutTask from "./pages/encoder/PayoutTask";

// Reports Pages
import ReportsOverview from "./pages/admin/ReportsOverview";
import VotersAddress from "./pages/admin/VotersAddress";
import ProfileAddress from "./pages/admin/ProfileAddress";
import FamilyVotersAddress from "./pages/admin/FamilyVotersAddress";
import FamilyProfileAddress from "./pages/admin/FamilyProfileAddress";
import MissingBarangayAnalysis from "./pages/admin/MissingBarangayAnalysis";

// Protected route for online Firebase login
const ProtectedRoute = ({ children, adminOnly = false }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (currentUser) => {
      if (currentUser) {
        try {
          const userDoc = await getDoc(doc(db, "users", currentUser.uid));
          const role = userDoc.exists() ? userDoc.data().role : null;

          if (adminOnly && role !== "admin") setUser(null);
          else setUser(currentUser);
        } catch {
          setUser(null);
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [adminOnly]);

  if (loading) {
    return (
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          height: "100vh",
          background: "#f7f7f7",
        }}
      >
        <p style={{ color: "#1f8ef1", fontWeight: "bold" }}>Checking authentication...</p>
      </div>
    );
  }

  return user ? children : <Navigate to="/login" replace />;
};

// Offline Protected Route
const OfflineProtectedRoute = ({ children, requiredRole }) => {
  const role = localStorage.getItem("role");

  if (!role || (requiredRole && role !== requiredRole)) return <Navigate to="/login" replace />;

  return children;
};

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Navigate to="/login" replace />} />
        <Route path="/login" element={<Login />} />

        {/* Offline Home / Dashboard */}
        <Route
          path="/home"
          element={
            <OfflineProtectedRoute>
              <Dashboard />
            </OfflineProtectedRoute>
          }
        />

        {/* Online Firebase Admin Routes */}
        <Route
          path="/admin"
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminDashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/pcvl"
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminPcvlMgt />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/voters"
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminVotersProfileMgt />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/reports/overview"
          element={
            <ProtectedRoute adminOnly={true}>
              <ReportsOverview />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/reports/political-status/voters-address"
          element={
            <ProtectedRoute adminOnly={true}>
              <VotersAddress />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/reports/political-status/profile-address"
          element={
            <ProtectedRoute adminOnly={true}>
              <ProfileAddress />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/reports/family-composition/voters-address"
          element={
            <ProtectedRoute adminOnly={true}>
              <FamilyVotersAddress />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/reports/family-composition/profile-address"
          element={
            <ProtectedRoute adminOnly={true}>
              <FamilyProfileAddress />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/analysis/missing-barangay"
          element={
            <ProtectedRoute adminOnly={true}>
              <MissingBarangayAnalysis />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/family-tree"
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminFamilyTree />
            </ProtectedRoute>
          }
        />

        {/* Offline Admin Routes */}
        <Route
          path="/admin/user-management"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <UserManagement />
            </OfflineProtectedRoute>
          }
        />
        <Route
          path="/encoding/admin"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <AdminEncoding />
            </OfflineProtectedRoute>
          }
        />
        <Route
          path="/encoding/admin/import-tasks"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <AdminImportTask />
            </OfflineProtectedRoute>
          }
        />
        <Route
          path="/admin/tasks"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <AdminTask />
            </OfflineProtectedRoute>
          }
        />
        <Route
          path="/admin/payouts-offline"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <PayoutManagement />
            </OfflineProtectedRoute>
          }
        />
        <Route
          path="/admin/payout-monitoring"
          element={
            <OfflineProtectedRoute requiredRole="admin">
              <PayoutMonitoring />
            </OfflineProtectedRoute>
          }
        />

        {/* Offline Encoder Routes */}
        <Route
          path="/encoder/encoding"
          element={
            <OfflineProtectedRoute requiredRole="encoder">
              <EncoderEncoding />
            </OfflineProtectedRoute>
          }
        />

        <Route
          path="/encoder/payout-task"
          element={
            <OfflineProtectedRoute requiredRole="encoder">
              <PayoutTask />
            </OfflineProtectedRoute>
          }
        />
        <Route path="/encoder" element={<Navigate to="/encoder/encoding" replace />} />

        {/* Default redirect */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}

export default App;